export const extraQuestions: Q[] = [

  // ══ Part 5 Level 1 (IDs 126-225) ══
  { id: 126, part: 5, difficulty: 1, question: "All staff must _____ their ID badges while on company premises.", options: ["wear", "wearing", "worn", "wears"], answer: 0, explanation: "mustの後は動詞の原形。" },
  { id: 127, part: 5, difficulty: 1, question: "The office is closed _____ Sundays.", options: ["on", "in", "at", "by"], answer: 0, explanation: "曜日には前置詞onを使う。" },
  { id: 128, part: 5, difficulty: 1, question: "The new product has received _____ reviews from customers.", options: ["positive", "positively", "positiveness", "position"], answer: 0, explanation: "名詞reviewsを修飾するので形容詞positiveが正しい。" },
  { id: 129, part: 5, difficulty: 1, question: "We _____ the client's proposal yesterday.", options: ["received", "receive", "receiving", "reception"], answer: 0, explanation: "yesterdayは過去を示す→過去形received。" },
  { id: 130, part: 5, difficulty: 1, question: "The department store is open _____ 10 a.m. _____ 9 p.m.", options: ["from / to", "since / until", "in / at", "from / at"], answer: 0, explanation: "「from A to B」= AからBまで。時間範囲の基本表現。" },
  { id: 131, part: 5, difficulty: 1, question: "Please _____ your name and contact information on the form.", options: ["write", "wrote", "written", "writing"], answer: 0, explanation: "Please + 動詞原形。" },
  { id: 132, part: 5, difficulty: 1, question: "The meeting _____ postponed until further notice.", options: ["has been", "have been", "is been", "are been"], answer: 0, explanation: "主語The meetingは単数→has been。現在完了受動態。" },
  { id: 133, part: 5, difficulty: 1, question: "There are _____ parking spaces available near the entrance.", options: ["several", "much", "a little", "less"], answer: 0, explanation: "可算名詞spacesにはseveralが使える。muchは不可算名詞に使う。" },
  { id: 134, part: 5, difficulty: 1, question: "She has _____ in this company for five years.", options: ["been working", "worked", "work", "works"], answer: 0, explanation: "「for + 期間」と継続を表す場合は現在完了進行形が自然。" },
  { id: 135, part: 5, difficulty: 1, question: "Please call us _____ you have any questions.", options: ["if", "although", "despite", "while"], answer: 0, explanation: "「if = もし〜なら」。条件節の基本接続詞。" },
  { id: 136, part: 5, difficulty: 1, question: "The _____ of the new branch will be next month.", options: ["opening", "open", "opened", "openly"], answer: 0, explanation: "冠詞theの後は名詞。openingは「開店・開業」を意味する名詞。" },
  { id: 137, part: 5, difficulty: 1, question: "This product is _____ in three different sizes.", options: ["available", "avail", "availability", "availably"], answer: 0, explanation: "be + 形容詞。availableは「入手可能な」。" },
  { id: 138, part: 5, difficulty: 1, question: "The train arrives _____ 8:30 every morning.", options: ["at", "on", "in", "by"], answer: 0, explanation: "特定の時刻には前置詞atを使う。" },
  { id: 139, part: 5, difficulty: 1, question: "All participants are requested to _____ the registration form.", options: ["complete", "completing", "completed", "completion"], answer: 0, explanation: "「be requested to + 動詞原形」。" },
  { id: 140, part: 5, difficulty: 1, question: "The new employee was _____ to the team during the morning meeting.", options: ["introduced", "introducing", "introduce", "introduction"], answer: 0, explanation: "「was + 過去分詞」で受動態。introduceの過去分詞はintroduced。" },
  { id: 141, part: 5, difficulty: 1, question: "This café is popular _____ young professionals.", options: ["among", "between", "within", "of"], answer: 0, explanation: "3者以上のグループで「人気がある」場合はamong。2者間はbetween。" },
  { id: 142, part: 5, difficulty: 1, question: "We are pleased to _____ that the project has been completed.", options: ["announce", "say", "tell", "speak"], answer: 0, explanation: "「pleased to announce」はビジネス文書の定型表現。" },
  { id: 143, part: 5, difficulty: 1, question: "The store offers free _____ on orders over ¥5,000.", options: ["shipping", "ship", "shipped", "shipment"], answer: 0, explanation: "「free shipping（送料無料）」。shippingは名詞。" },
  { id: 144, part: 5, difficulty: 1, question: "The new policy will _____ effect from January 1.", options: ["take", "come", "go", "get"], answer: 0, explanation: "「take effect（発効する）」はTOEIC頻出コロケーション。" },
  { id: 145, part: 5, difficulty: 1, question: "The workshop will be _____ by a certified trainer.", options: ["led", "lead", "leading", "leader"], answer: 0, explanation: "「will be + 過去分詞」で未来の受動態。leadの過去分詞はled。" },
  { id: 146, part: 5, difficulty: 1, question: "Our company has been in _____ for over 30 years.", options: ["business", "businesses", "work", "operation"], answer: 0, explanation: "「in business = 営業中・事業を営んでいる」。" },
  { id: 147, part: 5, difficulty: 1, question: "The restaurant is located _____ the fifth floor.", options: ["on", "in", "at", "by"], answer: 0, explanation: "フロア（階）の前置詞はon。「on the fifth floor」。" },
  { id: 148, part: 5, difficulty: 1, question: "Could you _____ the document to my email address?", options: ["send", "sent", "sending", "sends"], answer: 0, explanation: "Could you + 動詞原形。" },
  { id: 149, part: 5, difficulty: 1, question: "We look forward _____ hearing from you soon.", options: ["to", "for", "at", "of"], answer: 0, explanation: "「look forward to + -ing」。toは前置詞なのでingが続く。" },
  { id: 150, part: 5, difficulty: 1, question: "The flight was delayed _____ heavy fog.", options: ["due to", "because", "owing", "since"], answer: 0, explanation: "「due to（〜のため）」。後に名詞句が来る前置詞句。" },
  { id: 151, part: 5, difficulty: 1, question: "Our customer service team is _____ 24 hours a day.", options: ["available", "capable", "possible", "able"], answer: 0, explanation: "「available（利用可能な）」= サービスや人が利用できる状態。" },
  { id: 152, part: 5, difficulty: 1, question: "Please _____ us know if you need any assistance.", options: ["let", "make", "have", "get"], answer: 0, explanation: "「let us know（お知らせください）」は定型表現。" },
  { id: 153, part: 5, difficulty: 1, question: "The company will _____ an annual report at the end of the quarter.", options: ["release", "relax", "reveal", "resign"], answer: 0, explanation: "「release an annual report（年次報告書を発表する）」。" },
  { id: 154, part: 5, difficulty: 1, question: "The _____ fee for the conference is ¥3,000 per person.", options: ["registration", "register", "registering", "registered"], answer: 0, explanation: "「registration fee（登録料）」。名詞feeを修飾する名詞registration。" },
  { id: 155, part: 5, difficulty: 1, question: "This ticket is _____ for travel on weekdays only.", options: ["valid", "valued", "value", "validation"], answer: 0, explanation: "「valid（有効な）」= チケット・文書などが有効であること。" },
  { id: 156, part: 5, difficulty: 1, question: "Customers can _____ their orders online or by phone.", options: ["place", "put", "set", "make"], answer: 0, explanation: "「place an order（注文する）」はTOEIC頻出コロケーション。" },
  { id: 157, part: 5, difficulty: 1, question: "The seminar is _____ to all department heads.", options: ["open", "opened", "opening", "openly"], answer: 0, explanation: "「be open to（〜に開放されている）」。形容詞open。" },
  { id: 158, part: 5, difficulty: 1, question: "The deadline for applications is _____ April 30.", options: ["by", "on", "until", "at"], answer: 0, explanation: "「by（〜までに）」= 締め切りを示す前置詞。" },
  { id: 159, part: 5, difficulty: 1, question: "The repair work is _____ to take approximately two hours.", options: ["expected", "expecting", "expect", "expectation"], answer: 0, explanation: "「is expected to + 動詞原形」= 〜する見込みである。" },
  { id: 160, part: 5, difficulty: 1, question: "I would like to _____ an appointment with Dr. Smith.", options: ["make", "do", "have", "get"], answer: 0, explanation: "「make an appointment（予約を取る）」はTOEIC頻出コロケーション。" },
  { id: 161, part: 5, difficulty: 1, question: "Parking is _____ in the lot behind the building.", options: ["available", "availed", "availing", "availability"], answer: 0, explanation: "「Parking is available（駐車場が利用できる）」。形容詞available。" },
  { id: 162, part: 5, difficulty: 1, question: "We apologize _____ the inconvenience caused.", options: ["for", "about", "of", "to"], answer: 0, explanation: "「apologize for（〜について謝る）」。前置詞for。" },
  { id: 163, part: 5, difficulty: 1, question: "The budget was _____ by the finance committee last week.", options: ["approved", "approving", "approve", "approval"], answer: 0, explanation: "「was + 過去分詞」で受動態。approveの過去分詞はapproved。" },
  { id: 164, part: 5, difficulty: 1, question: "Please _____ your profile up to date on the company website.", options: ["keep", "hold", "maintain", "stay"], answer: 0, explanation: "「keep + 目的語 + 形容詞」= 〜を〜の状態に保つ。" },
  { id: 165, part: 5, difficulty: 1, question: "_____ you have any questions, please contact us.", options: ["Should", "Although", "Despite", "While"], answer: 0, explanation: "「Should you have（もしご質問があれば）」= if you haveの丁寧な文語的表現。" },
  { id: 166, part: 5, difficulty: 1, question: "The hotel is a short _____ from the conference center.", options: ["walk", "walking", "walked", "walker"], answer: 0, explanation: "「a short walk（少し歩いた距離）」。walkは名詞として使える。" },
  { id: 167, part: 5, difficulty: 1, question: "The company will _____ all employees with new safety equipment.", options: ["provide", "supply", "give", "present"], answer: 0, explanation: "「provide A with B（AにBを提供する）」はTOEIC頻出コロケーション。" },
  { id: 168, part: 5, difficulty: 1, question: "The invoice _____ be paid within 30 days.", options: ["must", "should", "might", "could"], answer: 0, explanation: "請求書の支払い期限は義務を示す→mustが最も強い表現。" },
  { id: 169, part: 5, difficulty: 1, question: "The conference room is _____ for up to 20 people.", options: ["designed", "intended", "suited", "able"], answer: 0, explanation: "「designed for（〜に向けて設計された）」。部屋の収容人数を表す文脈。" },
  { id: 170, part: 5, difficulty: 1, question: "The manager asked us to _____ the report by end of day.", options: ["submit", "hand", "offer", "present"], answer: 0, explanation: "「submit a report（報告書を提出する）」。submitはTOEIC頻出動詞。" },
  { id: 171, part: 5, difficulty: 1, question: "All payments must be made _____ advance.", options: ["in", "by", "with", "ahead of"], answer: 0, explanation: "「in advance（事前に）」はTOEIC超頻出表現。" },
  { id: 172, part: 5, difficulty: 1, question: "The package should _____ within three business days.", options: ["arrive", "arriving", "arrived", "arrives"], answer: 0, explanation: "should + 動詞原形。" },
  { id: 173, part: 5, difficulty: 1, question: "Please _____ the attached document for more details.", options: ["refer to", "look at", "check on", "see through"], answer: 0, explanation: "「refer to（〜を参照する）」はビジネス文書で最も格式のある表現。" },
  { id: 174, part: 5, difficulty: 1, question: "Our offices are _____ in five countries.", options: ["located", "locate", "location", "locating"], answer: 0, explanation: "「be located（〜に位置している）」。受動態の形容詞的用法。" },
  { id: 175, part: 5, difficulty: 1, question: "The venue can _____ up to 500 guests.", options: ["accommodate", "contain", "seat", "host"], answer: 0, explanation: "「accommodate（収容する）」はTOEIC頻出動詞。" },
  { id: 176, part: 5, difficulty: 1, question: "The new model is _____ energy-efficient than the previous one.", options: ["more", "most", "much", "very"], answer: 0, explanation: "比較級を作るにはmore + 形容詞。" },
  { id: 177, part: 5, difficulty: 1, question: "The annual picnic will be _____ weather permitting.", options: ["held", "hold", "having", "happened"], answer: 0, explanation: "「will be held（開催される予定）」。行事の開催にはholdの受動態を使う。" },
  { id: 178, part: 5, difficulty: 1, question: "Ms. Johnson will be _____ charge of the marketing campaign.", options: ["in", "on", "at", "of"], answer: 0, explanation: "「in charge of（〜を担当している）」はTOEIC頻出表現。" },
  { id: 179, part: 5, difficulty: 1, question: "The presentation was so _____ that everyone stayed for the Q&A.", options: ["engaging", "engaged", "engagement", "engage"], answer: 0, explanation: "so + 形容詞。「engaging（魅力的な）」は形容詞。" },
  { id: 180, part: 5, difficulty: 1, question: "Please _____ the reservation by calling our toll-free number.", options: ["confirm", "confirmation", "confirmed", "confirming"], answer: 0, explanation: "Please + 動詞原形。" },
  { id: 181, part: 5, difficulty: 1, question: "The construction is _____ to be finished by March.", options: ["scheduled", "planning", "expected", "supposed"], answer: 0, explanation: "「is scheduled to（〜する予定）」はTOEIC頻出表現。" },
  { id: 182, part: 5, difficulty: 1, question: "_____ completing the form, please submit it to reception.", options: ["After", "While", "Before", "Until"], answer: 0, explanation: "「After completing（記入した後）」。afterの後はing形。" },
  { id: 183, part: 5, difficulty: 1, question: "The library is closed _____ the holidays.", options: ["during", "while", "for", "over"], answer: 0, explanation: "「during the holidays（休日の間）」。期間を表す前置詞during。" },
  { id: 184, part: 5, difficulty: 1, question: "We are _____ to inform you that your application has been accepted.", options: ["pleased", "happy", "glad", "delighted"], answer: 0, explanation: "「pleased to inform」はビジネス文書の最も格式高い表現。" },
  { id: 185, part: 5, difficulty: 1, question: "The job _____ was posted on the company website.", options: ["listing", "list", "listed", "lists"], answer: 0, explanation: "「job listing（求人掲載）」。listingは名詞。" },
  { id: 186, part: 5, difficulty: 1, question: "All new hires must _____ a one-week orientation program.", options: ["complete", "attend", "participate", "join"], answer: 0, explanation: "「complete a program（プログラムを修了する）」。completeはTOEIC頻出動詞。" },
  { id: 187, part: 5, difficulty: 1, question: "Please ensure that all items are _____ labeled before shipping.", options: ["properly", "proper", "property", "properties"], answer: 0, explanation: "動詞labeledを修飾するには副詞properly。" },
  { id: 188, part: 5, difficulty: 1, question: "The company is committed _____ reducing its carbon footprint.", options: ["to", "for", "in", "of"], answer: 0, explanation: "「be committed to + -ing（〜することに取り組んでいる）」。toは前置詞。" },
  { id: 189, part: 5, difficulty: 1, question: "The _____ will be distributed before the meeting starts.", options: ["agenda", "agendas", "agreement", "announcement"], answer: 0, explanation: "「agenda（議題・アジェンダ）」。会議関連で頻出の名詞。" },
  { id: 190, part: 5, difficulty: 1, question: "The document needs to be _____ by a notary.", options: ["certified", "certify", "certification", "certifying"], answer: 0, explanation: "「needs to be + 過去分詞（受動態）」。certifyの過去分詞はcertified。" },
  { id: 191, part: 5, difficulty: 1, question: "Employees must obtain _____ from their supervisor before taking leave.", options: ["approval", "approve", "approved", "approvingly"], answer: 0, explanation: "「obtain approval（承認を得る）」。obtainの目的語に名詞approval。" },
  { id: 192, part: 5, difficulty: 1, question: "The company is planning to _____ its manufacturing capacity.", options: ["expand", "expansion", "expanded", "expanding"], answer: 0, explanation: "「plan to + 動詞原形」。expandが正しい。" },
  { id: 193, part: 5, difficulty: 1, question: "A _____ deposit of 30% is required to confirm your booking.", options: ["non-refundable", "non-refunding", "not-refund", "unrefunded"], answer: 0, explanation: "「non-refundable deposit（返金不可のデポジット）」。" },
  { id: 194, part: 5, difficulty: 1, question: "The company will be _____ for any damage caused during delivery.", options: ["responsible", "response", "responsibly", "responding"], answer: 0, explanation: "「be responsible for（〜に責任がある）」。形容詞responsible。" },
  { id: 195, part: 5, difficulty: 1, question: "Please complete the form in _____ letters.", options: ["capital", "capitalize", "capitalized", "captial"], answer: 0, explanation: "「in capital letters（大文字で）」。フォーム記入の定型表現。" },
  { id: 196, part: 5, difficulty: 1, question: "The survey results will be kept _____ confidential.", options: ["strictly", "serious", "strict", "seriously"], answer: 0, explanation: "形容詞confidentialを修飾するには副詞strictly。" },
  { id: 197, part: 5, difficulty: 1, question: "The _____ for the annual dinner will be distributed tomorrow.", options: ["invitations", "inviting", "invites", "invited"], answer: 0, explanation: "「invitations（招待状）」。可算名詞の複数形。" },
  { id: 198, part: 5, difficulty: 1, question: "Sales figures for the _____ quarter exceeded expectations.", options: ["previous", "prior", "past", "former"], answer: 0, explanation: "「previous quarter（前四半期）」。previousは「直前の」。" },
  { id: 199, part: 5, difficulty: 1, question: "The new cafeteria has _____ for over 200 people.", options: ["seating", "seats", "seated", "sit"], answer: 0, explanation: "「seating for（〜人分の座席）」。seatingは不可算名詞。" },
  { id: 200, part: 5, difficulty: 1, question: "The board meeting was _____ for two hours.", options: ["held", "hold", "holding", "holder"], answer: 0, explanation: "「was held（開催された）」= holdの受動態。" },
  { id: 201, part: 5, difficulty: 1, question: "_____ the poor weather, the outdoor event was a great success.", options: ["Despite", "Although", "Even", "However"], answer: 0, explanation: "「Despite + 名詞句（〜にもかかわらず）」。althoughは接続詞で節が続く。" },
  { id: 202, part: 5, difficulty: 1, question: "Please _____ to our newsletter to receive monthly updates.", options: ["subscribe", "register", "sign", "apply"], answer: 0, explanation: "「subscribe to（〜を購読する）」。動詞subscribe。" },
  { id: 203, part: 5, difficulty: 1, question: "The workshop is _____ for beginners with no prior experience.", options: ["suitable", "suited", "suiting", "suits"], answer: 0, explanation: "「suitable for（〜に適した）」。形容詞suitable。" },
  { id: 204, part: 5, difficulty: 1, question: "The company will _____ its first overseas office in Singapore.", options: ["open", "start", "begin", "launch"], answer: 0, explanation: "「open an office（事務所を開設する）」。openが最も自然なコロケーション。" },
  { id: 205, part: 5, difficulty: 1, question: "They plan to _____ a new product line next spring.", options: ["launch", "open", "begin", "release"], answer: 0, explanation: "「launch a product（製品を発売する）」はTOEIC頻出コロケーション。" },
  { id: 206, part: 5, difficulty: 1, question: "The customer asked _____ a full refund.", options: ["for", "of", "to", "about"], answer: 0, explanation: "「ask for（〜を求める）」。前置詞for。" },
  { id: 207, part: 5, difficulty: 1, question: "The training _____ will run from Monday to Friday.", options: ["session", "sessions", "seminar", "workshop"], answer: 0, explanation: "「training session（研修セッション）」は1回の研修を指す最も一般的な表現。" },
  { id: 208, part: 5, difficulty: 1, question: "Please make sure the lights are _____ before leaving.", options: ["turned off", "turning off", "turn off", "off turning"], answer: 0, explanation: "「make sure + that節」の受動態構文。" },
  { id: 209, part: 5, difficulty: 1, question: "The manager left a _____ for you at the front desk.", options: ["message", "mail", "note", "word"], answer: 0, explanation: "「leave a message（伝言を残す）」はTOEIC頻出コロケーション。" },
  { id: 210, part: 5, difficulty: 1, question: "Tickets are _____ on a first-come, first-served basis.", options: ["sold", "issued", "distributed", "allocated"], answer: 0, explanation: "「sold on a first-come, first-served basis（先着順で販売される）」。" },
  { id: 211, part: 5, difficulty: 1, question: "The hiring manager will _____ candidates next week.", options: ["interview", "talk", "speak", "meet"], answer: 0, explanation: "「interview candidates（候補者を面接する）」。動詞interviewが最も適切。" },
  { id: 212, part: 5, difficulty: 1, question: "The price includes all taxes and _____ charges.", options: ["service", "serving", "serviced", "serviceable"], answer: 0, explanation: "「service charges（サービス料）」。名詞serviceが名詞chargesを修飾する。" },
  { id: 213, part: 5, difficulty: 1, question: "All team members are _____ to attend the kick-off meeting.", options: ["required", "requiring", "require", "requirement"], answer: 0, explanation: "「are required to（〜することが求められる）」。受動態。" },
  { id: 214, part: 5, difficulty: 1, question: "The CEO will _____ the company's new strategy at the annual meeting.", options: ["present", "present with", "presentation", "presenting"], answer: 0, explanation: "「present（発表する）」。助動詞willの後は動詞原形。" },
  { id: 215, part: 5, difficulty: 1, question: "The factory operates _____ a week, seven days a week.", options: ["24 hours", "all day", "round-the-clock", "without stop"], answer: 0, explanation: "「24 hours a week」ではなく文脈で「24時間体制」を示す。ここでは最も一般的な24 hoursを選ぶ。" },
  { id: 216, part: 5, difficulty: 1, question: "Please _____ any errors in the document and return it to us.", options: ["correct", "correction", "correcting", "corrected"], answer: 0, explanation: "Please + 動詞原形。correctが正しい。" },
  { id: 217, part: 5, difficulty: 1, question: "The company _____ a new headquarters building last year.", options: ["built", "build", "building", "builds"], answer: 0, explanation: "last yearは過去→過去形built。" },
  { id: 218, part: 5, difficulty: 1, question: "You can _____ the nearest branch using our store locator.", options: ["find", "search", "look", "seek"], answer: 0, explanation: "「find（見つける）」= 店舗ロケーターで最寄り店舗を探す文脈に最適。" },
  { id: 219, part: 5, difficulty: 1, question: "The report was _____ on time despite several challenges.", options: ["completed", "completing", "complete", "completion"], answer: 0, explanation: "「was completed（完了した）」。受動態の過去形。" },
  { id: 220, part: 5, difficulty: 1, question: "Please _____ the form and return it within one week.", options: ["sign", "write", "check", "mark"], answer: 0, explanation: "「sign the form（書類に署名する）」。signが最も適切なコロケーション。" },
  { id: 221, part: 5, difficulty: 1, question: "The company will _____ a new branch in Osaka next year.", options: ["open", "make", "start", "create"], answer: 0, explanation: "「open a branch（支店を開設する）」はTOEIC頻出コロケーション。" },
  { id: 222, part: 5, difficulty: 1, question: "Employees are asked to _____ the safety guidelines at all times.", options: ["follow", "obey", "observe", "comply"], answer: 0, explanation: "「follow guidelines（ガイドラインに従う）」。followが最も自然な動詞。" },
  { id: 223, part: 5, difficulty: 1, question: "The conference will _____ in the Grand Ballroom on the second floor.", options: ["take place", "take effect", "take on", "take off"], answer: 0, explanation: "「take place（開催される）」はTOEIC超頻出コロケーション。" },
  { id: 224, part: 5, difficulty: 1, question: "All guests must _____ their names at the entrance.", options: ["register", "sign", "write", "list"], answer: 0, explanation: "「register（登録する）」= 入場時の氏名登録に使う最も適切な動詞。" },
  { id: 225, part: 5, difficulty: 1, question: "The renovation project is expected to be _____ by the end of the year.", options: ["finished", "finishing", "finish", "finishes"], answer: 0, explanation: "「be expected to be + 過去分詞」= 〜されると見込まれる。" },

  // ══ Part 5 Level 2 (IDs 226-325) ══
  { id: 226, part: 5, difficulty: 2, question: "The new policy will _____ all part-time workers.", options: ["affect", "effect", "impact on", "influence on"], answer: 0, explanation: "affect（動詞）= 〜に影響を与える。effectは名詞。" },
  { id: 227, part: 5, difficulty: 2, question: "The manager spoke highly of her team's _____ during the crisis.", options: ["performance", "perform", "performing", "performer"], answer: 0, explanation: "「spoke highly of + 名詞」。performanceは「業績・パフォーマンス」を意味する名詞。" },
  { id: 228, part: 5, difficulty: 2, question: "A _____ increase in revenue was reported in the third quarter.", options: ["considerable", "considerably", "considering", "consideration"], answer: 0, explanation: "名詞increaseを修飾するには形容詞considerable。「considerable（かなりの）」。" },
  { id: 229, part: 5, difficulty: 2, question: "Please _____ that the data is accurate before submitting the report.", options: ["ensure", "assure", "insure", "secure"], answer: 0, explanation: "「ensure（確認する・確かめる）」= 何かが確実に行われるようにする。assureは人を安心させる。" },
  { id: 230, part: 5, difficulty: 2, question: "_____ the tight deadline, the team delivered an excellent presentation.", options: ["Despite", "Although", "Even though", "Because of"], answer: 0, explanation: "「Despite + 名詞句」。althoughは接続詞で節が必要。" },
  { id: 231, part: 5, difficulty: 2, question: "The new regulations will be in _____ starting next April.", options: ["effect", "force", "operation", "practice"], answer: 0, explanation: "「in effect（有効・施行中）」= 規則・法律が効力を持っている状態。" },
  { id: 232, part: 5, difficulty: 2, question: "The sales team _____ its quarterly target for the third time in a row.", options: ["exceeded", "reached", "achieved", "surpassed"], answer: 0, explanation: "「exceed（上回る）」= 目標を超える。surpassedも正しいが、TOEICではexceedが最頻出。" },
  { id: 233, part: 5, difficulty: 2, question: "The price of raw materials has _____ significantly over the past year.", options: ["risen", "raised", "arisen", "arose"], answer: 0, explanation: "rise（自動詞）→ risen。raise（他動詞）は目的語が必要。" },
  { id: 234, part: 5, difficulty: 2, question: "The project manager is _____ for coordinating all team activities.", options: ["responsible", "responsible for", "in charge", "accountable"], answer: 0, explanation: "「responsible（責任のある）」= 形容詞単体でも使えるが、ここでは文構造上responsibleが補語として正しい。" },
  { id: 235, part: 5, difficulty: 2, question: "We are currently _____ a new marketing strategy.", options: ["developing", "develop", "developed", "development"], answer: 0, explanation: "be + -ing形で現在進行形。developingが正しい。" },
  { id: 236, part: 5, difficulty: 2, question: "The committee has _____ the proposal after reviewing all submissions.", options: ["approved", "agreed", "accepted", "authorized"], answer: 0, explanation: "「approve a proposal（提案を承認する）」。approvedが最も適切なコロケーション。" },
  { id: 237, part: 5, difficulty: 2, question: "The company plans to _____ its workforce by 15% next year.", options: ["reduce", "decrease", "cut", "lower"], answer: 0, explanation: "「reduce its workforce（人員を削減する）」。reduceはTOEIC頻出動詞。" },
  { id: 238, part: 5, difficulty: 2, question: "_____ attending the conference, she met several potential clients.", options: ["While", "During", "When", "As"], answer: 0, explanation: "「While + -ing（〜しながら・〜している間に）」。duringは前置詞で名詞が続く。" },
  { id: 239, part: 5, difficulty: 2, question: "The _____ of the new software has improved team efficiency.", options: ["introduction", "introduce", "introducing", "introduced"], answer: 0, explanation: "「the introduction of（〜の導入）」。名詞introductionが正しい。" },
  { id: 240, part: 5, difficulty: 2, question: "The report contains several _____ errors that need to be corrected.", options: ["minor", "minors", "minorly", "minority"], answer: 0, explanation: "名詞errorsを修飾するには形容詞minor。「minor errors（軽微なエラー）」。" },
  { id: 241, part: 5, difficulty: 2, question: "Candidates must submit their applications _____ the closing date.", options: ["before", "by", "prior", "until"], answer: 1, explanation: "「by（〜までに）」= 締め切りを示す。priorは前置詞ではなく形容詞。" },
  { id: 242, part: 5, difficulty: 2, question: "The new regulations are _____ to take effect next month.", options: ["due", "scheduled", "expected", "about"], answer: 0, explanation: "「due to take effect（発効予定）」= 予定されている。dueは「予定の」を意味する形容詞。" },
  { id: 243, part: 5, difficulty: 2, question: "The employee handbook is _____ to all staff on the intranet.", options: ["accessible", "available", "accessible to", "obtainable"], answer: 2, explanation: "「accessible to（〜がアクセスできる）」= accessible toで人を後置する。availableも使えるがここではaccessible toが文法的に最適。" },
  { id: 244, part: 5, difficulty: 2, question: "The factory was shut _____ for maintenance last weekend.", options: ["down", "up", "off", "out"], answer: 0, explanation: "「shut down（操業停止する）」はTOEIC頻出フレーズ。" },
  { id: 245, part: 5, difficulty: 2, question: "The company is _____ in providing high-quality customer service.", options: ["committed to", "dedicated to", "devoted to", "engaged in"], answer: 0, explanation: "「committed to（〜に取り組んでいる）」はTOEIC頻出表現。どれも正しいが文脈上最も一般的。" },
  { id: 246, part: 5, difficulty: 2, question: "The new branch will _____ operations in January.", options: ["begin", "commence", "start", "open"], answer: 1, explanation: "「commence operations（操業開始する）」。commenceはformalなビジネス用語。beginも正しいがcommenceが上位語として正解とされることが多い。" },
  { id: 247, part: 5, difficulty: 2, question: "The merger was _____ after months of negotiation.", options: ["finalized", "finished", "concluded", "completed"], answer: 0, explanation: "「finalize（最終決定する）」= 合意・契約などを正式に完成させる。M&A文脈で頻出。" },
  { id: 248, part: 5, difficulty: 2, question: "The company has _____ its sales forecast for the coming year.", options: ["revised", "reviewed", "renewed", "reformed"], answer: 0, explanation: "「revise a forecast（予測を修正する）」はTOEIC頻出コロケーション。" },
  { id: 249, part: 5, difficulty: 2, question: "The CEO made a _____ speech at the company's 50th anniversary.", options: ["keynote", "key", "main", "principal"], answer: 0, explanation: "「keynote speech（基調講演）」はTOEIC頻出表現。" },
  { id: 250, part: 5, difficulty: 2, question: "The new system will _____ the need for manual data entry.", options: ["eliminate", "remove", "delete", "erase"], answer: 0, explanation: "「eliminate the need for（〜の必要性をなくす）」はTOEIC頻出コロケーション。" },
  { id: 251, part: 5, difficulty: 2, question: "All employees are _____ to wear safety helmets in the construction area.", options: ["required", "forced", "obliged", "compelled"], answer: 0, explanation: "「be required to（〜することが求められる）」はTOEIC頻出受動態。" },
  { id: 252, part: 5, difficulty: 2, question: "The survey showed that _____ 80% of customers were satisfied with the service.", options: ["nearly", "about", "approximately", "almost"], answer: 0, explanation: "「nearly（ほぼ・もう少しで）」= 数値の前に置いて「約〜」を意味する副詞。" },
  { id: 253, part: 5, difficulty: 2, question: "The company will _____ a decision on the new location by Friday.", options: ["reach", "make", "take", "come to"], answer: 0, explanation: "「reach a decision（決定に達する）」はTOEIC頻出コロケーション。make a decisionも正しいが、reach a decisionも重要。" },
  { id: 254, part: 5, difficulty: 2, question: "The _____ results of the clinical trial were very promising.", options: ["preliminary", "initial", "early", "prior"], answer: 0, explanation: "「preliminary results（予備的な結果）」= 最終結果の前の暫定的な結果。ビジネス・研究文脈で頻出。" },
  { id: 255, part: 5, difficulty: 2, question: "Ms. Park has _____ extensive experience in international trade.", options: ["gained", "gotten", "acquired", "obtained"], answer: 0, explanation: "「gain experience（経験を積む）」はTOEIC頻出コロケーション。" },
  { id: 256, part: 5, difficulty: 2, question: "The two companies agreed to _____ their resources to develop the new product.", options: ["combine", "share", "pool", "merge"], answer: 2, explanation: "「pool resources（リソースを結集する）」= 複数者がリソースを持ち寄る。TOEICで頻出のコロケーション。" },
  { id: 257, part: 5, difficulty: 2, question: "The manager will _____ the results of the survey with the board.", options: ["share", "tell", "inform", "notify"], answer: 0, explanation: "「share results with（〜に結果を共有する）」はTOEIC頻出コロケーション。" },
  { id: 258, part: 5, difficulty: 2, question: "The project has been _____ due to budget constraints.", options: ["postponed", "delayed", "put off", "deferred"], answer: 0, explanation: "「postponed（延期された）」はTOEIC頻出語。delayed、put offも類義語だがpostponedが最もフォーマル。" },
  { id: 259, part: 5, difficulty: 2, question: "The factory produces _____ 1,000 units per day.", options: ["approximately", "about", "nearly", "around"], answer: 0, explanation: "「approximately（約〜）」はビジネス数値の近似値を示す最も格式高い副詞。" },
  { id: 260, part: 5, difficulty: 2, question: "The new system is expected to _____ operational costs by 20%.", options: ["reduce", "lower", "cut", "decrease"], answer: 0, explanation: "「reduce costs（コストを削減する）」はTOEIC超頻出コロケーション。" },
  { id: 261, part: 5, difficulty: 2, question: "The marketing team is _____ a new campaign for the holiday season.", options: ["planning", "plan", "planned", "plans"], answer: 0, explanation: "be + -ing形の現在進行形。planningが正しい。" },
  { id: 262, part: 5, difficulty: 2, question: "The meeting _____ for two hours and ended without a resolution.", options: ["lasted", "continued", "went", "ran"], answer: 0, explanation: "「last（続く）」= 時間的な継続を示す自動詞。「lasted for two hours」。" },
  { id: 263, part: 5, difficulty: 2, question: "The new office building _____ ten floors and a rooftop terrace.", options: ["features", "includes", "contains", "has"], answer: 0, explanation: "「feature（特徴として持つ）」= 建物・製品が特長を備えていることを強調する動詞。" },
  { id: 264, part: 5, difficulty: 2, question: "The product was recalled _____ a safety concern.", options: ["due to", "because of", "owing to", "as a result of"], answer: 0, explanation: "いずれも「〜のため」を意味するが、「due to」が最もTOEICで頻出。名詞句が続く点でも共通。" },
  { id: 265, part: 5, difficulty: 2, question: "He has been with the company _____ over ten years.", options: ["for", "since", "during", "throughout"], answer: 0, explanation: "「for + 期間（継続）」= 期間の長さを示す。sinceは開始時点を示す。" },
  { id: 266, part: 5, difficulty: 2, question: "The board of directors _____ a vote on the acquisition proposal.", options: ["held", "took", "conducted", "ran"], answer: 0, explanation: "「hold a vote（投票を行う）」= 公式の会議での投票に使う。conduct a voteも可。" },
  { id: 267, part: 5, difficulty: 2, question: "The company has been _____ for its environmentally friendly practices.", options: ["recognized", "rewarded", "praised", "acknowledged"], answer: 0, explanation: "「recognized for（〜で認められる）」はTOEIC頻出表現。" },
  { id: 268, part: 5, difficulty: 2, question: "The CEO's _____ vision helped transform the company into a global leader.", options: ["strategic", "strategically", "strategize", "strategy"], answer: 0, explanation: "名詞visionを修飾するには形容詞strategic。「strategic vision（戦略的なビジョン）」。" },
  { id: 269, part: 5, difficulty: 2, question: "The company _____ its profits by investing in new technologies.", options: ["increased", "grew", "raised", "boosted"], answer: 3, explanation: "「boost profits（利益を大幅に向上させる）」= boostは急激・大幅な増加を示す。" },
  { id: 270, part: 5, difficulty: 2, question: "The proposal must be _____ before it can be sent to the client.", options: ["revised", "reviewing", "review", "reviewed"], answer: 0, explanation: "「must be + 過去分詞」で受動態。reviseの過去分詞はrevised。" },
  { id: 271, part: 5, difficulty: 2, question: "The workshop is _____ to improve employees' communication skills.", options: ["designed", "aimed", "intended", "meant"], answer: 0, explanation: "「designed to（〜するために設計された）」はTOEIC頻出表現。aimは「aimed at + -ing」の形が一般的。" },
  { id: 272, part: 5, difficulty: 2, question: "The manager _____ the team with detailed instructions before the project began.", options: ["provided", "gave", "offered", "supplied"], answer: 0, explanation: "「provide A with B（AにBを提供する）」は最もTOEICで頻出のコロケーション。" },
  { id: 273, part: 5, difficulty: 2, question: "The quarterly report must be _____ to all shareholders.", options: ["distributed", "shared", "sent", "circulated"], answer: 0, explanation: "「distributed（配布された）」= 文書を多数の受取人に配ることを意味する。" },
  { id: 274, part: 5, difficulty: 2, question: "The survey _____ that most employees prefer flexible work arrangements.", options: ["indicated", "showed", "revealed", "suggested"], answer: 0, explanation: "「indicate（示す）」= データ・調査が何かを示すときに使う最も一般的な動詞。" },
  { id: 275, part: 5, difficulty: 2, question: "We are _____ sorry for any inconvenience this may cause.", options: ["truly", "very", "so", "quite"], answer: 0, explanation: "「truly sorry（本当に申し訳ない）」はビジネス文書・謝罪文の定型表現。" },
  { id: 276, part: 5, difficulty: 2, question: "The director _____ the importance of meeting the deadline.", options: ["emphasized", "stressed", "highlighted", "underlined"], answer: 0, explanation: "「emphasize（強調する）」はTOEIC頻出動詞。stressed/highlighted/underlinedも類義語。" },
  { id: 277, part: 5, difficulty: 2, question: "Applications submitted _____ the deadline will not be considered.", options: ["after", "beyond", "past", "over"], answer: 0, explanation: "「after the deadline（締め切り後）」。afterが最も一般的な前置詞。" },
  { id: 278, part: 5, difficulty: 2, question: "The company will _____ a press conference to address the issue.", options: ["hold", "have", "give", "make"], answer: 0, explanation: "「hold a press conference（記者会見を開く）」はTOEIC頻出コロケーション。" },
  { id: 279, part: 5, difficulty: 2, question: "Sales _____ by 12% in the second quarter, surpassing expectations.", options: ["grew", "increased", "rose", "jumped"], answer: 2, explanation: "riseは自動詞で「増加する」。sales rose（売上が上昇した）は最も正確な表現。" },
  { id: 280, part: 5, difficulty: 2, question: "The branch manager has the _____ to approve expenses up to ¥100,000.", options: ["authority", "right", "power", "permission"], answer: 0, explanation: "「authority to（〜する権限）」はビジネス文脈で最もフォーマルな表現。" },
  { id: 281, part: 5, difficulty: 2, question: "The company is _____ new staff for the upcoming holiday season.", options: ["recruiting", "hiring", "seeking", "looking for"], answer: 0, explanation: "「recruiting（採用活動をしている）」はビジネス文脈で最もフォーマルな表現。" },
  { id: 282, part: 5, difficulty: 2, question: "The supplier agreed to _____ the delivery time by one week.", options: ["shorten", "reduce", "cut", "decrease"], answer: 0, explanation: "「shorten the delivery time（納期を短縮する）」。shortenがdelivery timeとの最自然なコロケーション。" },
  { id: 283, part: 5, difficulty: 2, question: "The CEO announced plans to _____ two departments to improve efficiency.", options: ["merge", "combine", "integrate", "consolidate"], answer: 0, explanation: "「merge departments（部門を合併する）」はTOEIC頻出コロケーション。" },
  { id: 284, part: 5, difficulty: 2, question: "The conference attracted _____ from over 20 countries.", options: ["participants", "attendees", "delegates", "members"], answer: 0, explanation: "「participants（参加者）」はTOEIC頻出語。delegatesはより公式な会議で使う。" },
  { id: 285, part: 5, difficulty: 2, question: "The marketing department is _____ a new campaign to attract younger consumers.", options: ["launching", "starting", "beginning", "initiating"], answer: 0, explanation: "「launch a campaign（キャンペーンを開始する）」はTOEIC頻出コロケーション。" },
  { id: 286, part: 5, difficulty: 2, question: "The IT team successfully _____ the new software across all departments.", options: ["implemented", "installed", "introduced", "deployed"], answer: 0, explanation: "「implement（実施する・導入する）」= システムやプロセスを実際に運用状態にすること。" },
  { id: 287, part: 5, difficulty: 2, question: "The report was _____ to all board members before the meeting.", options: ["circulated", "distributed", "sent", "shared"], answer: 0, explanation: "「circulated（回覧された）」= 文書が複数人に順次配られることを示す。" },
  { id: 288, part: 5, difficulty: 2, question: "The two companies entered _____ a joint venture agreement.", options: ["into", "in", "upon", "onto"], answer: 0, explanation: "「enter into（〜を締結する）」= 合意・契約を正式に結ぶ。" },
  { id: 289, part: 5, difficulty: 2, question: "Sales figures are _____ to improve once the new product is launched.", options: ["likely", "expected", "probable", "possible"], answer: 0, explanation: "「likely to（〜する可能性が高い）」はTOEIC頻出表現。" },
  { id: 290, part: 5, difficulty: 2, question: "The board _____ a new initiative to improve workplace diversity.", options: ["introduced", "launched", "announced", "proposed"], answer: 0, explanation: "「introduce an initiative（施策を導入する）」。introduceが新しい方針の開始に最も自然。" },
  { id: 291, part: 5, difficulty: 2, question: "The _____ cost of the renovation was significantly lower than estimated.", options: ["actual", "real", "true", "genuine"], answer: 0, explanation: "「actual cost（実際のコスト）」= 見積もりと対比させる文脈で最も適切。" },
  { id: 292, part: 5, difficulty: 2, question: "Please submit your expense report _____ of each month.", options: ["by the end", "at the end", "on the end", "until the end"], answer: 0, explanation: "「by the end of（〜の終わりまでに）」= 期限を示す最も一般的な表現。" },
  { id: 293, part: 5, difficulty: 2, question: "The training program has been _____ to meet the needs of new employees.", options: ["designed", "tailored", "customized", "modified"], answer: 0, explanation: "「designed to meet（〜するために設計された）」はTOEIC頻出表現。" },
  { id: 294, part: 5, difficulty: 2, question: "The airline will _____ passengers with a full refund for cancelled flights.", options: ["provide", "offer", "give", "compensate"], answer: 0, explanation: "「provide A with B（AにBを提供する）」= 航空会社が払い戻しを提供するケース。" },
  { id: 295, part: 5, difficulty: 2, question: "The team _____ weekly to review progress on the project.", options: ["meets", "gathers", "assembles", "convenes"], answer: 0, explanation: "「meet（集まる）」は最も一般的な動詞。convenes/assemblesはよりフォーマル。" },
  { id: 296, part: 5, difficulty: 2, question: "New safety measures have been _____ in response to the recent accident.", options: ["implemented", "introduced", "adopted", "established"], answer: 0, explanation: "「implement safety measures（安全対策を実施する）」はTOEIC頻出コロケーション。" },
  { id: 297, part: 5, difficulty: 2, question: "The hotel offers a _____ discount to guests who book directly.", options: ["special", "specific", "particular", "exclusive"], answer: 0, explanation: "「special discount（特別割引）」はTOEIC超頻出コロケーション。" },
  { id: 298, part: 5, difficulty: 2, question: "The _____ version of the software will be released next quarter.", options: ["updated", "latest", "newest", "revised"], answer: 1, explanation: "「latest version（最新バージョン）」は製品リリースの文脈で最も一般的。" },
  { id: 299, part: 5, difficulty: 2, question: "We _____ all inquiries within one business day.", options: ["respond to", "reply", "answer", "address"], answer: 0, explanation: "「respond to inquiries（問い合わせに対応する）」はTOEIC頻出コロケーション。" },
  { id: 300, part: 5, difficulty: 2, question: "The new store is _____ conveniently located near the train station.", options: ["very", "quite", "so", "rather"], answer: 1, explanation: "quiteは「かなり」と「まったく」両方の意味を持つが、「quite conveniently」は中程度の副詞として使う。いずれも文法的に正しいがquiteが最もTOEIC的。" },
  { id: 301, part: 5, difficulty: 2, question: "The manager _____ the meeting to discuss the project's progress.", options: ["called", "organized", "arranged", "scheduled"], answer: 0, explanation: "「call a meeting（会議を招集する）」はTOEIC頻出コロケーション。" },
  { id: 302, part: 5, difficulty: 2, question: "The company is _____ to expand its product line.", options: ["planning", "considering", "looking to", "aiming"], answer: 0, explanation: "「planning to expand（拡大を計画している）」は最も明確な意図を示す表現。" },
  { id: 303, part: 5, difficulty: 2, question: "The seminar will _____ topics such as time management and leadership.", options: ["cover", "include", "address", "discuss"], answer: 0, explanation: "「cover topics（トピックを扱う）」はTOEIC頻出コロケーション。" },
  { id: 304, part: 5, difficulty: 2, question: "The department _____ a budget of ¥5 million for the new project.", options: ["allocated", "assigned", "granted", "awarded"], answer: 0, explanation: "「allocate a budget（予算を割り当てる）」はTOEIC頻出コロケーション。" },
  { id: 305, part: 5, difficulty: 2, question: "We need to _____ the contract before the end of the week.", options: ["finalize", "finish", "complete", "close"], answer: 0, explanation: "「finalize a contract（契約を最終決定する）」はビジネス文脈で最も適切。" },
  { id: 306, part: 5, difficulty: 2, question: "The company _____ a strategic partnership with a leading tech firm.", options: ["formed", "made", "created", "established"], answer: 0, explanation: "「form a partnership（パートナーシップを結ぶ）」はTOEIC頻出コロケーション。" },
  { id: 307, part: 5, difficulty: 2, question: "The CEO _____ the team for their outstanding work on the project.", options: ["commended", "praised", "thanked", "recognized"], answer: 0, explanation: "「commend（称賛する）」= フォーマルな状況での称賛を示す動詞。TOEICで出る。" },
  { id: 308, part: 5, difficulty: 2, question: "The _____ figures show a steady improvement in customer satisfaction.", options: ["latest", "last", "recent", "current"], answer: 0, explanation: "「latest figures（最新の数値）」= 最も最近のデータを指す。latesは「最も直近の」を強調。" },
  { id: 309, part: 5, difficulty: 2, question: "All shipments must be _____ before they leave the warehouse.", options: ["inspected", "checked", "examined", "reviewed"], answer: 0, explanation: "「inspect（検査する）」= 工場・倉庫での品質検査を示す最も適切な動詞。" },
  { id: 310, part: 5, difficulty: 2, question: "The company's new headquarters will _____ 500 employees.", options: ["house", "hold", "accommodate", "contain"], answer: 0, explanation: "「house（収容する・収めて置く）」= 建物が人やオフィスを収容することに使う動詞。" },
  { id: 311, part: 5, difficulty: 2, question: "The board _____ the merger after a thorough review.", options: ["approved", "agreed to", "accepted", "authorized"], answer: 0, explanation: "「approve the merger（合併を承認する）」はTOEIC頻出コロケーション。" },
  { id: 312, part: 5, difficulty: 2, question: "Our products are _____ distributed throughout Asia.", options: ["widely", "broadly", "largely", "extensively"], answer: 0, explanation: "「widely distributed（広く流通している）」はTOEIC頻出コロケーション。" },
  { id: 313, part: 5, difficulty: 2, question: "The conference room has been _____ for tomorrow's meeting.", options: ["reserved", "booked", "scheduled", "arranged"], answer: 0, explanation: "「reserve a room（部屋を予約する）」はTOEIC頻出コロケーション。" },
  { id: 314, part: 5, difficulty: 2, question: "The _____ of the new product exceeded the company's expectations.", options: ["success", "performance", "results", "outcome"], answer: 0, explanation: "「the success of（〜の成功）」= 最もシンプルで直接的な表現。" },
  { id: 315, part: 5, difficulty: 2, question: "Please submit your _____ before the registration deadline.", options: ["application", "apply", "applicant", "applicable"], answer: 0, explanation: "「submit your application（応募書類を提出する）」はTOEIC頻出コロケーション。" },
  { id: 316, part: 5, difficulty: 2, question: "The team worked _____ to complete the project on time.", options: ["diligently", "hard", "closely", "carefully"], answer: 0, explanation: "「diligently（勤勉に）」はTOEIC頻出副詞。hardも正しいが、diligentlyがより上位語。" },
  { id: 317, part: 5, difficulty: 2, question: "The store will be closed for _____ on Mondays.", options: ["maintenance", "repair", "renovation", "inspection"], answer: 0, explanation: "「closed for maintenance（メンテナンスのため休業）」はTOEIC頻出表現。" },
  { id: 318, part: 5, difficulty: 2, question: "The company has _____ its market share in the past three years.", options: ["increased", "expanded", "grown", "enlarged"], answer: 0, explanation: "「increase market share（市場シェアを拡大する）」はTOEIC頻出コロケーション。" },
  { id: 319, part: 5, difficulty: 2, question: "All staff members are _____ to complete the online safety training.", options: ["required", "expected", "asked", "urged"], answer: 0, explanation: "「required to complete（〜することが必須）」= 義務を示す最も強い表現。" },
  { id: 320, part: 5, difficulty: 2, question: "The budget _____ was approved without any modifications.", options: ["proposal", "plan", "request", "application"], answer: 0, explanation: "「budget proposal（予算案）」はTOEIC頻出コロケーション。" },
  { id: 321, part: 5, difficulty: 2, question: "The company will _____ its annual shareholders' meeting next week.", options: ["hold", "have", "conduct", "organize"], answer: 0, explanation: "「hold a meeting（会議を開催する）」はTOEIC超頻出コロケーション。" },
  { id: 322, part: 5, difficulty: 2, question: "The new service is expected to _____ customers from a wider demographic.", options: ["attract", "appeal", "draw", "invite"], answer: 0, explanation: "「attract customers（顧客を引き付ける）」はTOEIC頻出コロケーション。" },
  { id: 323, part: 5, difficulty: 2, question: "The financial report _____ an overview of the company's performance.", options: ["provides", "gives", "offers", "presents"], answer: 0, explanation: "「provide an overview（概要を提供する）」はTOEIC頻出コロケーション。" },
  { id: 324, part: 5, difficulty: 2, question: "The team _____ significant progress on the new system last week.", options: ["made", "achieved", "had", "reached"], answer: 0, explanation: "「make progress（進歩する）」はTOEIC超頻出コロケーション。" },
  { id: 325, part: 5, difficulty: 2, question: "The company offers _____ benefits to its full-time employees.", options: ["comprehensive", "complete", "full", "entire"], answer: 0, explanation: "「comprehensive benefits（包括的な福利厚生）」はビジネス文脈の頻出表現。" },

  // ══ Part 5 Level 3 (IDs 326-425) ══
  { id: 326, part: 5, difficulty: 3, question: "The expansion plan will _____ a substantial investment in infrastructure.", options: ["require", "need", "demand", "necessitate"], answer: 3, explanation: "「necessitate（必要とする）」= フォーマルな上位語。requireも正しいが、難問ではnecessitateが正解となるケースが多い。" },
  { id: 327, part: 5, difficulty: 3, question: "The committee is _____ to reach a consensus by the end of the week.", options: ["hoping", "aiming", "seeking", "endeavoring"], answer: 3, explanation: "「endeavoring to（努めている）」= 努力・取り組みを示すフォーマルな表現。" },
  { id: 328, part: 5, difficulty: 3, question: "The CEO's decision was _____ by all members of the executive team.", options: ["endorsed", "supported", "backed", "approved"], answer: 0, explanation: "「endorse（支持する・承認する）」= 公式な立場での支持を示す最上位語。" },
  { id: 329, part: 5, difficulty: 3, question: "The factory will _____ production by 30% to meet increased demand.", options: ["scale up", "increase", "expand", "boost"], answer: 0, explanation: "「scale up production（生産規模を拡大する）」はビジネス英語の重要フレーズ。" },
  { id: 330, part: 5, difficulty: 3, question: "The company has _____ strict confidentiality protocols to protect client data.", options: ["implemented", "established", "adopted", "put in place"], answer: 0, explanation: "「implement protocols（プロトコルを実施する）」はTOEIC頻出コロケーション。" },
  { id: 331, part: 5, difficulty: 3, question: "The annual report _____ a detailed breakdown of the company's financial position.", options: ["contains", "includes", "presents", "provides"], answer: 3, explanation: "「provide a breakdown（内訳を提供する）」= 情報を詳細に提供するときのフォーマル表現。" },
  { id: 332, part: 5, difficulty: 3, question: "The new product line was _____ after extensive market research.", options: ["developed", "launched", "introduced", "created"], answer: 1, explanation: "「launched after research（調査後に発売された）」。launchは製品の市場投入を示す。" },
  { id: 333, part: 5, difficulty: 3, question: "Employees are _____ to complete the mandatory cybersecurity training.", options: ["obligated", "required", "expected", "instructed"], answer: 0, explanation: "「obligated to（義務づけられている）」= mandatoryと組み合わさり法的・組織的義務を示す。" },
  { id: 334, part: 5, difficulty: 3, question: "The organization must _____ with all applicable environmental regulations.", options: ["comply", "conform", "adhere", "follow"], answer: 0, explanation: "「comply with regulations（規制を遵守する）」はTOEIC超頻出表現。" },
  { id: 335, part: 5, difficulty: 3, question: "The _____ of the project depends on securing adequate funding.", options: ["feasibility", "success", "viability", "outcome"], answer: 2, explanation: "「viability（実行可能性・採算性）」= プロジェクトが成立するかどうかを示す上位語。" },
  { id: 336, part: 5, difficulty: 3, question: "The company will _____ its resources to the most profitable divisions.", options: ["allocate", "direct", "channel", "assign"], answer: 0, explanation: "「allocate resources（リソースを配分する）」はTOEIC頻出コロケーション。" },
  { id: 337, part: 5, difficulty: 3, question: "The board _____ a comprehensive review of the company's risk management practices.", options: ["commissioned", "ordered", "requested", "initiated"], answer: 0, explanation: "「commission a review（レビューを依頼・委託する）」= 外部機関への正式な依頼を示す。" },
  { id: 338, part: 5, difficulty: 3, question: "The proposal was _____ on the grounds that it exceeded the budget.", options: ["rejected", "refused", "denied", "declined"], answer: 0, explanation: "「reject a proposal（提案を却下する）」はTOEIC頻出コロケーション。" },
  { id: 339, part: 5, difficulty: 3, question: "The manager _____ the team about the upcoming changes to the work schedule.", options: ["notified", "informed", "advised", "told"], answer: 0, explanation: "「notify（通知する）」= 公式な変更事項を関係者に通知する動詞。" },
  { id: 340, part: 5, difficulty: 3, question: "The company's financial results _____ industry analysts' expectations.", options: ["exceeded", "surpassed", "outperformed", "beat"], answer: 2, explanation: "「outperform expectations（予想を上回る）」= 金融・ビジネス文脈で頻出の表現。" },
  { id: 341, part: 5, difficulty: 3, question: "The new policy _____ employees from disclosing confidential information.", options: ["prohibits", "prevents", "restricts", "bans"], answer: 0, explanation: "「prohibit from（〜することを禁止する）」は最もフォーマルな禁止表現。" },
  { id: 342, part: 5, difficulty: 3, question: "The task force was _____ to investigate the cause of the data breach.", options: ["established", "formed", "created", "set up"], answer: 0, explanation: "「establish a task force（タスクフォースを設置する）」はフォーマルな文脈の頻出表現。" },
  { id: 343, part: 5, difficulty: 3, question: "The company has _____ a strong reputation for innovation over the past decade.", options: ["built", "established", "developed", "created"], answer: 0, explanation: "「build a reputation（評判を築く）」はTOEIC頻出コロケーション。" },
  { id: 344, part: 5, difficulty: 3, question: "The relocation of the headquarters will be _____ in phases.", options: ["carried out", "conducted", "implemented", "executed"], answer: 0, explanation: "「carried out in phases（段階的に実施される）」。carry outは計画・作業の実行に使う。" },
  { id: 345, part: 5, difficulty: 3, question: "The project _____ significant delays due to supply chain disruptions.", options: ["encountered", "faced", "experienced", "suffered"], answer: 0, explanation: "「encounter delays（遅延に遭遇する）」。encounteredは予期しない問題に使う。" },
  { id: 346, part: 5, difficulty: 3, question: "The proposal was _____ by the CEO before being presented to the board.", options: ["reviewed", "examined", "scrutinized", "evaluated"], answer: 2, explanation: "「scrutinize（精査する）」= 非常に詳細に調べること。評価文書の精査に使う上位語。" },
  { id: 347, part: 5, difficulty: 3, question: "The company is _____ to increase its dividend payout next year.", options: ["poised", "ready", "prepared", "set"], answer: 0, explanation: "「poised to（〜する体勢が整っている）」= ビジネス・金融文脈で頻出の表現。" },
  { id: 348, part: 5, difficulty: 3, question: "A _____ analysis of the market confirmed strong growth potential.", options: ["thorough", "complete", "comprehensive", "detailed"], answer: 0, explanation: "「thorough analysis（徹底的な分析）」はTOEIC頻出コロケーション。" },
  { id: 349, part: 5, difficulty: 3, question: "The company has _____ measures to prevent future data security breaches.", options: ["put in place", "established", "implemented", "introduced"], answer: 0, explanation: "「put in place measures（対策を講じる）」はTOEIC頻出イディオム。" },
  { id: 350, part: 5, difficulty: 3, question: "The merger _____ the combined company to achieve greater economies of scale.", options: ["enabled", "allowed", "permitted", "helped"], answer: 0, explanation: "「enable A to do（AがBするのを可能にする）」はTOEIC頻出構文。" },
  { id: 351, part: 5, difficulty: 3, question: "The quarterly results _____ a significant improvement in profit margins.", options: ["reflected", "showed", "indicated", "demonstrated"], answer: 0, explanation: "「reflect（反映する）」= 数値やデータが実態を示すときに使う動詞。" },
  { id: 352, part: 5, difficulty: 3, question: "All employees are _____ to adhere to the company's code of conduct.", options: ["expected", "required", "obliged", "supposed"], answer: 0, explanation: "「expected to adhere（遵守することが期待されている）」は規範を示すフォーマルな表現。" },
  { id: 353, part: 5, difficulty: 3, question: "The committee _____ a series of recommendations to improve the hiring process.", options: ["issued", "made", "released", "produced"], answer: 0, explanation: "「issue recommendations（提言を出す）」はTOEIC頻出コロケーション。" },
  { id: 354, part: 5, difficulty: 3, question: "The company plans to _____ its global presence through strategic acquisitions.", options: ["strengthen", "expand", "extend", "broaden"], answer: 1, explanation: "「expand its global presence（グローバルプレゼンスを拡大する）」はビジネス文脈で最も頻出。" },
  { id: 355, part: 5, difficulty: 3, question: "The new regulation _____ all companies to report greenhouse gas emissions annually.", options: ["requires", "demands", "mandates", "compels"], answer: 2, explanation: "「mandate（義務づける）」= 法律・規制が義務を課すときに使う動詞。formalな上位語。" },
  { id: 356, part: 5, difficulty: 3, question: "The company will _____ its operations in the European market by year-end.", options: ["wind down", "scale back", "reduce", "curtail"], answer: 1, explanation: "「scale back operations（事業を縮小する）」はビジネス文脈で重要なフレーズ。" },
  { id: 357, part: 5, difficulty: 3, question: "The _____ of the negotiations resulted in a favorable trade agreement.", options: ["outcome", "result", "conclusion", "end"], answer: 0, explanation: "「outcome of negotiations（交渉の結果）」はTOEIC頻出コロケーション。" },
  { id: 358, part: 5, difficulty: 3, question: "The new software _____ employees to collaborate more effectively across teams.", options: ["enables", "allows", "permits", "helps"], answer: 0, explanation: "「enable employees to（従業員が〜できるようにする）」はTOEIC頻出構文。" },
  { id: 359, part: 5, difficulty: 3, question: "The management team _____ weekly to review the status of ongoing projects.", options: ["convenes", "meets", "gathers", "assembles"], answer: 0, explanation: "「convene（集まる・召集する）」= フォーマルな会議の開催を示す上位語。" },
  { id: 360, part: 5, difficulty: 3, question: "The project manager must _____ all risks before the project begins.", options: ["identify", "assess", "evaluate", "recognize"], answer: 0, explanation: "「identify risks（リスクを特定する）」= リスク管理プロセスの第一段階。" },
  { id: 361, part: 5, difficulty: 3, question: "The _____ of the new system will take approximately three months.", options: ["implementation", "installation", "deployment", "rollout"], answer: 0, explanation: "「implementation（実施・導入）」はTOEIC頻出語。より上位の概念。" },
  { id: 362, part: 5, difficulty: 3, question: "The company's _____ efforts have resulted in a 25% reduction in waste.", options: ["sustainability", "sustainable", "sustainably", "sustain"], answer: 1, explanation: "名詞effortsを修飾するには形容詞sustainable。「sustainable efforts（持続可能な取り組み）」。" },
  { id: 363, part: 5, difficulty: 3, question: "The board _____ the acquisition of a smaller competitor to expand market share.", options: ["approved", "agreed on", "sanctioned", "authorized"], answer: 2, explanation: "「sanction（公式に承認する）」= 権限を持つ機関が正式に許可すること。" },
  { id: 364, part: 5, difficulty: 3, question: "The company is _____ a strategic review of all its business units.", options: ["undertaking", "conducting", "performing", "executing"], answer: 0, explanation: "「undertake a review（レビューを実施する）」はフォーマルな文脈で最も適切。" },
  { id: 365, part: 5, difficulty: 3, question: "The proposed changes will _____ a significant impact on daily operations.", options: ["have", "make", "create", "produce"], answer: 0, explanation: "「have an impact on（〜に影響を与える）」はTOEIC超頻出コロケーション。" },
  { id: 366, part: 5, difficulty: 3, question: "The company _____ a new initiative to reduce energy consumption in its facilities.", options: ["launched", "started", "began", "introduced"], answer: 0, explanation: "「launch an initiative（取り組みを開始する）」はTOEIC頻出コロケーション。" },
  { id: 367, part: 5, difficulty: 3, question: "The _____ of the two companies is expected to create synergies.", options: ["merger", "combination", "consolidation", "integration"], answer: 0, explanation: "「merger（合併）」= 2社が合体して1社になること。M&A文脈で必須語彙。" },
  { id: 368, part: 5, difficulty: 3, question: "The manager _____ responsibility for the project's failure.", options: ["assumed", "took", "accepted", "bore"], answer: 0, explanation: "「assume responsibility（責任を引き受ける）」はTOEIC頻出コロケーション。" },
  { id: 369, part: 5, difficulty: 3, question: "The company's performance has been _____ affected by rising raw material costs.", options: ["adversely", "negatively", "poorly", "badly"], answer: 0, explanation: "「adversely affected（悪影響を受けた）」はTOEIC頻出コロケーション。" },
  { id: 370, part: 5, difficulty: 3, question: "The firm _____ a loss for the second consecutive quarter.", options: ["reported", "posted", "announced", "recorded"], answer: 1, explanation: "「post a loss（損失を計上する）」= 財務結果の発表に使う最も適切な動詞。" },
  { id: 371, part: 5, difficulty: 3, question: "The company's _____ to customer feedback has been praised.", options: ["responsiveness", "response", "responsibility", "responding"], answer: 0, explanation: "「responsiveness（反応の良さ）」= 顧客フィードバックへの迅速な対応力を示す。" },
  { id: 372, part: 5, difficulty: 3, question: "The deadline was _____ to accommodate the team's requests.", options: ["extended", "pushed back", "moved", "postponed"], answer: 0, explanation: "「extend a deadline（締め切りを延長する）」はTOEIC頻出コロケーション。" },
  { id: 373, part: 5, difficulty: 3, question: "The company _____ from the economic downturn more quickly than expected.", options: ["recovered", "rebounded", "bounced back", "resumed"], answer: 0, explanation: "「recover from（〜から回復する）」はTOEIC頻出表現。reboundedも可。" },
  { id: 374, part: 5, difficulty: 3, question: "All proposals must _____ the following criteria to be considered.", options: ["meet", "satisfy", "fulfill", "address"], answer: 0, explanation: "「meet criteria（基準を満たす）」はTOEIC超頻出コロケーション。" },
  { id: 375, part: 5, difficulty: 3, question: "The financial statements were _____ by an independent auditing firm.", options: ["audited", "reviewed", "examined", "verified"], answer: 0, explanation: "「audited by（〜によって監査された）」は財務文脈で最も適切な動詞。" },
  { id: 376, part: 5, difficulty: 3, question: "The _____ report highlights key trends in consumer behavior.", options: ["comprehensive", "complete", "overall", "inclusive"], answer: 0, explanation: "「comprehensive report（包括的なレポート）」はTOEIC頻出コロケーション。" },
  { id: 377, part: 5, difficulty: 3, question: "The company _____ its operations to three additional countries last year.", options: ["extended", "expanded", "grew", "spread"], answer: 1, explanation: "「expand operations（事業を拡大する）」はTOEIC超頻出コロケーション。" },
  { id: 378, part: 5, difficulty: 3, question: "The management team _____ the proposal after careful deliberation.", options: ["endorsed", "approved", "supported", "backed"], answer: 0, explanation: "「endorse a proposal（提案を支持する）」= 公式な立場での支持を示す動詞。" },
  { id: 379, part: 5, difficulty: 3, question: "All departments are _____ to submit their budget requests by Friday.", options: ["required", "expected", "asked", "urged"], answer: 0, explanation: "「required to submit（提出することが必須）」= 強い義務を示す。" },
  { id: 380, part: 5, difficulty: 3, question: "The audit _____ several discrepancies in the financial records.", options: ["uncovered", "found", "discovered", "revealed"], answer: 0, explanation: "「uncover discrepancies（不一致を発見する）」= 調査で隠れていた問題を発見するニュアンス。" },
  { id: 381, part: 5, difficulty: 3, question: "The company _____ a record profit of ¥10 billion last fiscal year.", options: ["posted", "reported", "announced", "achieved"], answer: 0, explanation: "「post a record profit（過去最高益を計上する）」は財務文脈の重要表現。" },
  { id: 382, part: 5, difficulty: 3, question: "The CEO _____ that the company would return to profitability within two years.", options: ["projected", "predicted", "forecast", "estimated"], answer: 0, explanation: "「project（見通す・予測する）」= CEOが将来の収益性について語るときに使う動詞。" },
  { id: 383, part: 5, difficulty: 3, question: "The company has _____ its focus on sustainable practices in recent years.", options: ["shifted", "changed", "moved", "turned"], answer: 0, explanation: "「shift its focus（フォーカスをシフトする）」はビジネス文脈で頻出のコロケーション。" },
  { id: 384, part: 5, difficulty: 3, question: "The acquisition _____ the company's product portfolio significantly.", options: ["broadened", "expanded", "widened", "extended"], answer: 0, explanation: "「broaden the portfolio（ポートフォリオを広げる）」はM&A文脈で頻出。" },
  { id: 385, part: 5, difficulty: 3, question: "A _____ of industry experts reviewed the company's environmental practices.", options: ["panel", "group", "team", "committee"], answer: 0, explanation: "「a panel of experts（専門家パネル）」はTOEIC頻出コロケーション。" },
  { id: 386, part: 5, difficulty: 3, question: "The project team _____ a detailed timeline for the rollout.", options: ["outlined", "drew up", "prepared", "created"], answer: 0, explanation: "「outline a timeline（タイムラインを概説する）」はプロジェクト管理文脈で頻出。" },
  { id: 387, part: 5, difficulty: 3, question: "The company's revenue _____ by 18% year-over-year.", options: ["grew", "increased", "rose", "jumped"], answer: 0, explanation: "「revenue grew by（収益が〜増加した）」= growは財務文脈で最もよく使われる動詞の一つ。" },
  { id: 388, part: 5, difficulty: 3, question: "The board _____ the restructuring plan, citing concerns about job losses.", options: ["rejected", "turned down", "opposed", "dismissed"], answer: 0, explanation: "「reject a plan（計画を却下する）」はTOEIC頻出コロケーション。" },
  { id: 389, part: 5, difficulty: 3, question: "The company has _____ a number of cost-cutting measures to improve profitability.", options: ["introduced", "implemented", "adopted", "taken"], answer: 1, explanation: "「implement measures（対策を実施する）」はTOEIC超頻出コロケーション。" },
  { id: 390, part: 5, difficulty: 3, question: "The _____ of the new product was delayed due to supply chain issues.", options: ["launch", "release", "introduction", "debut"], answer: 0, explanation: "「the launch of（〜の発売）」はTOEIC頻出表現。" },
  { id: 391, part: 5, difficulty: 3, question: "The company is _____ steps to improve cybersecurity across all its platforms.", options: ["taking", "making", "implementing", "adopting"], answer: 0, explanation: "「take steps to（〜するための措置を取る）」はTOEIC頻出コロケーション。" },
  { id: 392, part: 5, difficulty: 3, question: "The team _____ the data from multiple sources to prepare the report.", options: ["compiled", "collected", "gathered", "assembled"], answer: 0, explanation: "「compile data（データをまとめる）」は報告書作成文脈で最も適切な動詞。" },
  { id: 393, part: 5, difficulty: 3, question: "The quarterly meeting provided an opportunity to _____ strategies going forward.", options: ["reassess", "reconsider", "review", "evaluate"], answer: 0, explanation: "「reassess strategies（戦略を再評価する）」= reassessは方針を改めて見直すニュアンス。" },
  { id: 394, part: 5, difficulty: 3, question: "The company has _____ its environmental targets for the next decade.", options: ["set", "established", "determined", "outlined"], answer: 0, explanation: "「set targets（目標を設定する）」はTOEIC超頻出コロケーション。" },
  { id: 395, part: 5, difficulty: 3, question: "The product was _____ for its innovative design at the industry awards.", options: ["recognized", "awarded", "honored", "praised"], answer: 0, explanation: "「recognized for（〜で認められる）」はTOEIC頻出表現。" },
  { id: 396, part: 5, difficulty: 3, question: "The company will _____ a new line of eco-friendly products next year.", options: ["introduce", "launch", "release", "roll out"], answer: 0, explanation: "「introduce a product line（製品ラインを導入する）」はTOEIC頻出コロケーション。" },
  { id: 397, part: 5, difficulty: 3, question: "The director _____ a presentation on the company's five-year growth plan.", options: ["delivered", "gave", "made", "presented"], answer: 0, explanation: "「deliver a presentation（プレゼンを行う）」はTOEIC頻出コロケーション。" },
  { id: 398, part: 5, difficulty: 3, question: "The investment is expected to _____ returns within three years.", options: ["yield", "produce", "generate", "create"], answer: 0, explanation: "「yield returns（リターンをもたらす）」は投資文脈の重要なコロケーション。" },
  { id: 399, part: 5, difficulty: 3, question: "The merger is _____ to create the largest company in the industry.", options: ["expected", "projected", "predicted", "anticipated"], answer: 3, explanation: "「anticipated to（〜すると予想されている）」= 期待と予想を含むニュアンス。" },
  { id: 400, part: 5, difficulty: 3, question: "The company _____ record earnings for the fourth consecutive quarter.", options: ["reported", "posted", "announced", "achieved"], answer: 1, explanation: "「post record earnings（過去最高益を計上する）」は財務報告の重要表現。" },
  { id: 401, part: 5, difficulty: 3, question: "The training program is _____ to last three days.", options: ["estimated", "expected", "scheduled", "supposed"], answer: 2, explanation: "「scheduled to last（〜続く予定）」はTOEIC頻出表現。" },
  { id: 402, part: 5, difficulty: 3, question: "The policy _____ employees from accepting gifts from suppliers.", options: ["prohibits", "prevents", "bans", "restricts"], answer: 0, explanation: "「prohibit from（〜することを禁止する）」= フォーマルな禁止の最上位語。" },
  { id: 403, part: 5, difficulty: 3, question: "The company has _____ that it will meet its annual sales target.", options: ["confirmed", "assured", "promised", "guaranteed"], answer: 0, explanation: "「confirm that（〜を確認・宣言する）」は公式発表の文脈で使う。" },
  { id: 404, part: 5, difficulty: 3, question: "The _____ of the audit revealed no significant irregularities.", options: ["findings", "results", "conclusions", "outcomes"], answer: 0, explanation: "「findings of an audit（監査の調査結果）」はTOEIC頻出コロケーション。" },
  { id: 405, part: 5, difficulty: 3, question: "The company _____ a joint venture with a regional distributor.", options: ["established", "formed", "created", "set up"], answer: 1, explanation: "「form a joint venture（合弁会社を設立する）」はTOEIC頻出コロケーション。" },
  { id: 406, part: 5, difficulty: 3, question: "The team must _____ all options before making a final decision.", options: ["consider", "weigh", "evaluate", "assess"], answer: 1, explanation: "「weigh all options（すべての選択肢を検討する）」= 慎重に比較検討するニュアンス。" },
  { id: 407, part: 5, difficulty: 3, question: "The company _____ a new policy regarding remote work arrangements.", options: ["adopted", "implemented", "introduced", "established"], answer: 0, explanation: "「adopt a policy（方針を採用する）」はTOEIC頻出コロケーション。" },
  { id: 408, part: 5, difficulty: 3, question: "The _____ of the cost-cutting measures is expected within the fiscal year.", options: ["impact", "effect", "result", "consequence"], answer: 0, explanation: "「the impact of（〜の影響）」はTOEIC超頻出コロケーション。" },
  { id: 409, part: 5, difficulty: 3, question: "The company _____ a significant market share in the consumer electronics sector.", options: ["holds", "has", "owns", "controls"], answer: 0, explanation: "「hold market share（市場シェアを保有する）」はTOEIC頻出コロケーション。" },
  { id: 410, part: 5, difficulty: 3, question: "The launch of the new product _____ a wave of positive press coverage.", options: ["generated", "created", "sparked", "triggered"], answer: 0, explanation: "「generate coverage（注目・報道を生む）」はTOEIC頻出コロケーション。" },
  { id: 411, part: 5, difficulty: 3, question: "The company will _____ a series of workshops on leadership development.", options: ["host", "hold", "organize", "run"], answer: 0, explanation: "「host workshops（ワークショップを主催する）」はTOEIC頻出コロケーション。" },
  { id: 412, part: 5, difficulty: 3, question: "The management team _____ an agreement to restructure the company's debt.", options: ["reached", "made", "came to", "achieved"], answer: 0, explanation: "「reach an agreement（合意に達する）」はTOEIC超頻出コロケーション。" },
  { id: 413, part: 5, difficulty: 3, question: "The new facility was built to _____ modern manufacturing standards.", options: ["meet", "satisfy", "comply with", "adhere to"], answer: 0, explanation: "「meet standards（基準を満たす）」はTOEIC超頻出コロケーション。" },
  { id: 414, part: 5, difficulty: 3, question: "The company has _____ significant progress in its efforts to become carbon neutral.", options: ["made", "achieved", "shown", "demonstrated"], answer: 0, explanation: "「make progress（進歩する）」はTOEIC超頻出コロケーション。" },
  { id: 415, part: 5, difficulty: 3, question: "The _____ of the new branch office is scheduled for early next year.", options: ["opening", "launch", "establishment", "inauguration"], answer: 0, explanation: "「the opening of（〜の開設）」はTOEIC頻出表現。" },
  { id: 416, part: 5, difficulty: 3, question: "All staff members were _____ about the changes to the benefits package.", options: ["briefed", "informed", "notified", "told"], answer: 0, explanation: "「briefed（ブリーフィングを受けた）」= 具体的な情報提供を受けた状態を示す。" },
  { id: 417, part: 5, difficulty: 3, question: "The project _____ more resources than originally anticipated.", options: ["required", "needed", "demanded", "consumed"], answer: 0, explanation: "「require resources（リソースを必要とする）」はTOEIC頻出コロケーション。" },
  { id: 418, part: 5, difficulty: 3, question: "The board _____ on a plan to divest three non-core business units.", options: ["agreed", "decided", "voted", "settled"], answer: 0, explanation: "「agree on a plan（計画に合意する）」はTOEIC頻出コロケーション。" },
  { id: 419, part: 5, difficulty: 3, question: "The company _____ quarterly dividends to its shareholders.", options: ["pays", "distributes", "provides", "issues"], answer: 0, explanation: "「pay dividends（配当を支払う）」はTOEIC頻出コロケーション。" },
  { id: 420, part: 5, difficulty: 3, question: "The firm has _____ itself as a leader in sustainable packaging solutions.", options: ["positioned", "established", "branded", "identified"], answer: 0, explanation: "「position itself as（〜として位置づける）」はビジネス戦略文脈で頻出。" },
  { id: 421, part: 5, difficulty: 3, question: "The committee _____ the revised budget proposal with minor amendments.", options: ["adopted", "approved", "accepted", "passed"], answer: 0, explanation: "「adopt a proposal（提案を採択する）」= 委員会・議会で正式に採択するときに使う動詞。" },
  { id: 422, part: 5, difficulty: 3, question: "The company's stock _____ sharply after the announcement of the merger.", options: ["surged", "rose", "jumped", "increased"], answer: 0, explanation: "「surge（急騰する）」= 株価の急激な上昇を示す。金融ニュースで頻出。" },
  { id: 423, part: 5, difficulty: 3, question: "The CEO _____ a vision for the company to become a global leader by 2030.", options: ["articulated", "expressed", "stated", "described"], answer: 0, explanation: "「articulate a vision（ビジョンを明確に表現する）」はCEOの発言を表す上位語。" },
  { id: 424, part: 5, difficulty: 3, question: "The annual conference _____ an opportunity for industry leaders to network.", options: ["provides", "offers", "gives", "presents"], answer: 0, explanation: "「provide an opportunity（機会を提供する）」はTOEIC超頻出コロケーション。" },
  { id: 425, part: 5, difficulty: 3, question: "The company is _____ in the renewable energy sector for the first time.", options: ["venturing", "entering", "investing", "expanding"], answer: 0, explanation: "「venture into（〜に参入する）」= 新しい分野に踏み出すニュアンスを含む動詞。" },

  // ══ Part 5 Level 4 (IDs 426-525) ══
  { id: 426, part: 5, difficulty: 4, question: "The board of directors _____ the CEO's recommendation to divest the retail division.", options: ["ratified", "approved", "endorsed", "confirmed"], answer: 0, explanation: "「ratify（批准する）」= 正式な手続きで決定を承認すること。董事会の決議に使う最上位語。" },
  { id: 427, part: 5, difficulty: 4, question: "The contract _____ that all disputes shall be resolved through arbitration.", options: ["stipulates", "states", "says", "specifies"], answer: 0, explanation: "「stipulate（明記する・規定する）」= 契約書で条件を具体的に定めること。" },
  { id: 428, part: 5, difficulty: 4, question: "The firm's _____ growth has attracted the attention of institutional investors.", options: ["exponential", "rapid", "dramatic", "extraordinary"], answer: 0, explanation: "「exponential growth（指数関数的成長）」= 非常に急速な成長を示す定型表現。" },
  { id: 429, part: 5, difficulty: 4, question: "Management _____ all available options before recommending the acquisition.", options: ["exhausted", "considered", "reviewed", "evaluated"], answer: 0, explanation: "「exhaust all options（すべての選択肢を尽くす）」= 利用可能な選択肢をすべて検討する。" },
  { id: 430, part: 5, difficulty: 4, question: "The proposed amendment would _____ the liability of minority shareholders.", options: ["limit", "restrict", "curtail", "cap"], answer: 3, explanation: "「cap liability（責任に上限を設ける）」= 法的責任に上限を設ける金融・法律文脈での特有表現。" },
  { id: 431, part: 5, difficulty: 4, question: "The organization has _____ a task force to address the declining customer satisfaction scores.", options: ["convened", "established", "formed", "created"], answer: 0, explanation: "「convene a task force（タスクフォースを招集する）」= 特定目的のために会議・委員会を正式に召集する。" },
  { id: 432, part: 5, difficulty: 4, question: "The deal was contingent _____ regulatory approval from three different jurisdictions.", options: ["upon", "on", "with", "by"], answer: 0, explanation: "「contingent upon（〜を条件とする）」はM&A・法律文書で頻出の表現。uponはonより格式が高い。" },
  { id: 433, part: 5, difficulty: 4, question: "The company's _____ position has improved significantly following the debt restructuring.", options: ["liquidity", "financial", "cash", "monetary"], answer: 0, explanation: "「liquidity position（流動性の状況）」= 短期的な資金繰りの状態を示す財務用語。" },
  { id: 434, part: 5, difficulty: 4, question: "The audit committee _____ an independent review of the financial reporting process.", options: ["commissioned", "ordered", "requested", "initiated"], answer: 0, explanation: "「commission a review（レビューを委託する）」= 外部機関に正式に依頼する動詞。" },
  { id: 435, part: 5, difficulty: 4, question: "The company is _____ to reduce its reliance on a single supplier.", options: ["seeking to", "aiming to", "looking to", "working to"], answer: 3, explanation: "「working to reduce（〜削減に取り組んでいる）」= 具体的な行動を伴う進行中の努力を示す。" },
  { id: 436, part: 5, difficulty: 4, question: "The new regulation _____ significant compliance costs on financial institutions.", options: ["imposes", "places", "creates", "generates"], answer: 0, explanation: "「impose costs on（〜にコストを課す）」= 規制・法律が負担を与える文脈で使う。" },
  { id: 437, part: 5, difficulty: 4, question: "The company has _____ from a product-focused to a services-focused business model.", options: ["transitioned", "shifted", "moved", "changed"], answer: 0, explanation: "「transition from A to B（AからBへ移行する）」はビジネス変革を表すフォーマルな動詞。" },
  { id: 438, part: 5, difficulty: 4, question: "The CEO's remarks _____ market speculation about an imminent acquisition.", options: ["fueled", "sparked", "triggered", "prompted"], answer: 0, explanation: "「fuel speculation（憶測を煽る）」= 情報や発言が不確実な推測を促進する文脈。" },
  { id: 439, part: 5, difficulty: 4, question: "The _____ of the company's debt has been downgraded by a major rating agency.", options: ["rating", "credit rating", "creditworthiness", "grade"], answer: 1, explanation: "「credit rating（信用格付け）」= 格付け機関が評価する企業の信用度。金融文脈の必須語彙。" },
  { id: 440, part: 5, difficulty: 4, question: "The project team has _____ a comprehensive risk mitigation strategy.", options: ["devised", "developed", "created", "formulated"], answer: 0, explanation: "「devise a strategy（戦略を立案する）」= 独自の方策を考案するときに使う動詞。" },
  { id: 441, part: 5, difficulty: 4, question: "The management _____ that the company would achieve double-digit growth.", options: ["projected", "predicted", "anticipated", "forecast"], answer: 0, explanation: "「project growth（成長を見込む）」= 経営陣が将来の業績を予測する文脈での動詞。" },
  { id: 442, part: 5, difficulty: 4, question: "The _____ clause in the agreement allows either party to exit under specific conditions.", options: ["termination", "exit", "withdrawal", "cancellation"], answer: 0, explanation: "「termination clause（終了条項）」は契約書の重要用語。解約・解除の条件を定める条項。" },
  { id: 443, part: 5, difficulty: 4, question: "The company's _____ expenses have risen sharply due to increased regulatory scrutiny.", options: ["compliance", "legal", "administrative", "regulatory"], answer: 0, explanation: "「compliance expenses（コンプライアンスコスト）」= 規制遵守のためのコスト。" },
  { id: 444, part: 5, difficulty: 4, question: "The firm has _____ its position as the market leader through consistent innovation.", options: ["consolidated", "strengthened", "cemented", "reinforced"], answer: 2, explanation: "「cement its position（地位を盤石にする）」= ポジションを固化する最も強い動詞。" },
  { id: 445, part: 5, difficulty: 4, question: "The board _____ a motion to increase the dividend payout ratio.", options: ["passed", "approved", "voted on", "adopted"], answer: 0, explanation: "「pass a motion（動議を可決する）」は議会・委員会で使うフォーマルな動詞。" },
  { id: 446, part: 5, difficulty: 4, question: "The company _____ a 20% stake in the joint venture to a strategic investor.", options: ["divested", "sold", "transferred", "assigned"], answer: 0, explanation: "「divest a stake（出資持分を売却する）」= M&A・財務文脈で使う特定の動詞。" },
  { id: 447, part: 5, difficulty: 4, question: "The regulatory framework _____ a strict separation between commercial and investment banking.", options: ["mandates", "requires", "demands", "stipulates"], answer: 0, explanation: "「mandate（義務づける）」= 法律・規制が強制的に要求すること。" },
  { id: 448, part: 5, difficulty: 4, question: "The company's _____ model has evolved considerably since its founding.", options: ["business", "operating", "revenue", "commercial"], answer: 0, explanation: "「business model（ビジネスモデル）」はTOEIC頻出語。収益構造の仕組みを示す。" },
  { id: 449, part: 5, difficulty: 4, question: "The _____ review of the acquisition target revealed significant undisclosed liabilities.", options: ["due diligence", "legal", "financial", "independent"], answer: 0, explanation: "「due diligence review（デューデリジェンス調査）」= M&A前の徹底的な事業調査。" },
  { id: 450, part: 5, difficulty: 4, question: "The CFO _____ the board on the implications of the proposed restructuring.", options: ["briefed", "informed", "advised", "updated"], answer: 0, explanation: "「brief the board（取締役会にブリーフィングする）」= 要点を整理して正式に説明する動詞。" },
  { id: 451, part: 5, difficulty: 4, question: "The company has _____ a non-disclosure agreement with all potential investors.", options: ["executed", "signed", "completed", "finalized"], answer: 0, explanation: "「execute an agreement（合意書を締結する）」= 法律文書に署名して法的効力を持たせる。" },
  { id: 452, part: 5, difficulty: 4, question: "The _____ of the merger depends on shareholder approval at the upcoming meeting.", options: ["consummation", "completion", "finalization", "conclusion"], answer: 0, explanation: "「consummation of a merger（合併の完了）」= M&A完了を示すフォーマルな法律用語。" },
  { id: 453, part: 5, difficulty: 4, question: "The investment bank was retained to _____ the company through the IPO process.", options: ["advise", "guide", "assist", "support"], answer: 0, explanation: "「advise（アドバイザーとして支援する）」= 投資銀行がIPO等のプロセスで顧客を指導する動詞。" },
  { id: 454, part: 5, difficulty: 4, question: "The _____ of the new plant is expected to generate 500 jobs in the region.", options: ["commissioning", "opening", "launch", "startup"], answer: 0, explanation: "「commissioning（試運転・稼働開始）」= 工場・施設が正式に稼働を開始すること。" },
  { id: 455, part: 5, difficulty: 4, question: "The shareholders voted _____ to accept the buyout offer.", options: ["overwhelmingly", "predominantly", "largely", "significantly"], answer: 0, explanation: "「voted overwhelmingly（圧倒的多数で賛成した）」= 票決の結果を描写する副詞。" },
  { id: 456, part: 5, difficulty: 4, question: "The company's _____ was affected by a major recall of its flagship product.", options: ["reputation", "brand", "image", "credibility"], answer: 0, explanation: "「reputation（評判）」= 会社・ブランドへの社会的評価全般を示す。" },
  { id: 457, part: 5, difficulty: 4, question: "The finance team must _____ all expenditures against the annual budget.", options: ["reconcile", "compare", "check", "verify"], answer: 0, explanation: "「reconcile expenditures against budget（支出を予算と照合する）」= 会計の重要プロセス。" },
  { id: 458, part: 5, difficulty: 4, question: "The company has _____ robust internal controls to prevent financial fraud.", options: ["instituted", "established", "implemented", "introduced"], answer: 0, explanation: "「institute controls（管理体制を設ける）」= 制度・手続きを正式に設立する動詞。" },
  { id: 459, part: 5, difficulty: 4, question: "The _____ agreement prevents former employees from joining competitors for two years.", options: ["non-compete", "confidentiality", "non-disclosure", "exclusivity"], answer: 0, explanation: "「non-compete agreement（競業避止契約）」= 元従業員が競合他社に移ることを制限する契約。" },
  { id: 460, part: 5, difficulty: 4, question: "The company's profitability has been _____ by rising energy costs and supply disruptions.", options: ["eroded", "reduced", "diminished", "affected"], answer: 0, explanation: "「erode profitability（収益性を侵食する）」= 徐々に悪化させるニュアンスを持つ動詞。" },
  { id: 461, part: 5, difficulty: 4, question: "The board resolved to _____ the company's capital structure through a debt-for-equity swap.", options: ["restructure", "reorganize", "reform", "revamp"], answer: 0, explanation: "「restructure the capital structure（資本構成を再構築する）」= 財務エンジニアリング文脈の必須語彙。" },
  { id: 462, part: 5, difficulty: 4, question: "The analysts _____ the company's stock as a strong buy following the earnings release.", options: ["rated", "graded", "evaluated", "assessed"], answer: 0, explanation: "「rate a stock（株式を評価・格付けする）」= アナリストが投資推奨を与える動詞。" },
  { id: 463, part: 5, difficulty: 4, question: "The supply chain _____ during the pandemic exposed vulnerabilities in the company's operations.", options: ["disruption", "interruption", "breakdown", "failure"], answer: 0, explanation: "「supply chain disruption（サプライチェーンの混乱）」はCOVID後の定着語彙。" },
  { id: 464, part: 5, difficulty: 4, question: "The firm _____ an injunction to prevent its competitor from using its patented technology.", options: ["sought", "filed for", "applied for", "requested"], answer: 0, explanation: "「seek an injunction（差し止め命令を求める）」は法律文脈の重要表現。" },
  { id: 465, part: 5, difficulty: 4, question: "The _____ rate of the flagship product has raised concerns among quality assurance teams.", options: ["defect", "failure", "error", "fault"], answer: 0, explanation: "「defect rate（不良品率）」= 製品の製造工程における欠陥品の割合。品質管理の必須語彙。" },
  { id: 466, part: 5, difficulty: 4, question: "The management team identified three _____ for the underperforming division.", options: ["scenarios", "options", "strategies", "alternatives"], answer: 0, explanation: "「scenarios（シナリオ）」= 戦略立案における複数の将来シナリオを指す語彙。" },
  { id: 467, part: 5, difficulty: 4, question: "The company's _____ to the new market was methodical and well-planned.", options: ["entry", "approach", "expansion", "penetration"], answer: 3, explanation: "「market penetration（市場浸透）」= 新市場への参入と定着を示すマーケティング用語。" },
  { id: 468, part: 5, difficulty: 4, question: "The acquisition was _____ conditional on the target company achieving its EBITDA targets.", options: ["made", "rendered", "set", "structured"], answer: 0, explanation: "「made conditional on（〜を条件とした）」= M&A条件設定の表現。" },
  { id: 469, part: 5, difficulty: 4, question: "The _____ of the partnership hinges on both companies meeting their contractual obligations.", options: ["continuity", "sustainability", "durability", "longevity"], answer: 0, explanation: "「continuity（継続性）」= パートナーシップが維持されることを示す概念。" },
  { id: 470, part: 5, difficulty: 4, question: "The firm _____ its quarterly earnings guidance, citing stronger-than-expected demand.", options: ["raised", "upgraded", "revised upward", "increased"], answer: 2, explanation: "「revised upward（上方修正した）」= 業績予想の修正に使うフォーマルな表現。" },
  { id: 471, part: 5, difficulty: 4, question: "The company's _____ strategy involves acquiring smaller players to consolidate the market.", options: ["inorganic", "external", "acquisition-driven", "M&A"], answer: 0, explanation: "「inorganic growth strategy（非有機的成長戦略）」= 買収・提携による外部成長を意味するビジネス用語。" },
  { id: 472, part: 5, difficulty: 4, question: "The board is _____ its options regarding the proposed delisting from the stock exchange.", options: ["weighing", "evaluating", "considering", "assessing"], answer: 0, explanation: "「weighing options（選択肢を検討する）」= 慎重に選択肢を比較するニュアンスの動詞。" },
  { id: 473, part: 5, difficulty: 4, question: "The company issued a _____ to investors warning of potential earnings shortfalls.", options: ["profit warning", "earnings alert", "risk notice", "financial warning"], answer: 0, explanation: "「profit warning（業績警告）」= 利益目標が達成困難であることを市場に知らせる発表。" },
  { id: 474, part: 5, difficulty: 4, question: "The _____ of the restructuring plan is expected to take 18 months.", options: ["execution", "implementation", "rollout", "deployment"], answer: 0, explanation: "「execution of a plan（計画の実行）」= 戦略の実際の遂行を示す。" },
  { id: 475, part: 5, difficulty: 4, question: "The proposal was _____ after the CEO raised concerns about execution risk.", options: ["shelved", "abandoned", "rejected", "postponed"], answer: 0, explanation: "「shelved（棚上げされた）」= 計画が無期限に保留されること。abandonedより可逆的なニュアンス。" },
  { id: 476, part: 5, difficulty: 4, question: "The company's _____ obligations include filing quarterly and annual reports with the regulator.", options: ["disclosure", "reporting", "regulatory", "filing"], answer: 1, explanation: "「reporting obligations（報告義務）」= 定期的な開示を義務づける規制要件。" },
  { id: 477, part: 5, difficulty: 4, question: "The _____ of the patent expires in 2028, after which competitors can use the technology.", options: ["term", "duration", "validity", "period"], answer: 0, explanation: "「term of a patent（特許の存続期間）」= 法的に保護される期間を示す用語。" },
  { id: 478, part: 5, difficulty: 4, question: "The underwriter agreed to _____ any unsold shares in the initial public offering.", options: ["absorb", "purchase", "acquire", "buy back"], answer: 0, explanation: "「absorb unsold shares（売れ残り株式を引き受ける）」= 引受業者がIPOの残株を自ら取得する。" },
  { id: 479, part: 5, difficulty: 4, question: "The CFO _____ the need for tighter cash flow management given the upcoming debt maturity.", options: ["underscored", "emphasized", "highlighted", "stressed"], answer: 0, explanation: "「underscore（強調する）」= 重要性を特に際立たせる動詞。CFOの発言に使うフォーマルな語。" },
  { id: 480, part: 5, difficulty: 4, question: "The company's growth has been _____ by a series of successful product launches.", options: ["driven", "fueled", "powered", "boosted"], answer: 0, explanation: "「driven by（〜によって推進された）」は成長の要因を示すTOEIC頻出表現。" },
  { id: 481, part: 5, difficulty: 4, question: "The _____ period for the loan is five years, after which the principal must be repaid.", options: ["grace", "repayment", "maturity", "payment"], answer: 2, explanation: "「maturity period（満期期間）」= ローン・債券が満期を迎えるまでの期間。金融用語。" },
  { id: 482, part: 5, difficulty: 4, question: "The investment was structured to _____ the tax implications for all parties.", options: ["minimize", "reduce", "mitigate", "limit"], answer: 0, explanation: "「minimize tax implications（税務上の影響を最小化する）」はタックスプランニングの重要表現。" },
  { id: 483, part: 5, difficulty: 4, question: "The firm has _____ a strong track record in cross-border transactions.", options: ["established", "built", "developed", "created"], answer: 1, explanation: "「build a track record（実績を積む）」はTOEIC頻出コロケーション。" },
  { id: 484, part: 5, difficulty: 4, question: "The _____ of the spin-off will allow each entity to focus on its core competencies.", options: ["completion", "execution", "finalization", "consummation"], answer: 0, explanation: "「completion of a spin-off（スピンオフの完了）」= 親会社から子会社を独立させる手続きの終了。" },
  { id: 485, part: 5, difficulty: 4, question: "The proposed takeover is subject to _____ from the competition authority.", options: ["clearance", "approval", "authorization", "permission"], answer: 0, explanation: "「clearance from the competition authority（競争当局のクリアランス）」= M&Aに必要な独占禁止法上の承認。" },
  { id: 486, part: 5, difficulty: 4, question: "The company _____ a loss provision of ¥2 billion in anticipation of a lawsuit settlement.", options: ["recorded", "set aside", "booked", "reserved"], answer: 2, explanation: "「book a provision（引当金を計上する）」= 会計上の損失引当を財務諸表に記録する動詞。" },
  { id: 487, part: 5, difficulty: 4, question: "The CEO _____ that the strategic review would be completed by end of year.", options: ["indicated", "suggested", "signaled", "hinted"], answer: 0, explanation: "「indicate（示す）」= 公式または半公式な発言で方向性を示す動詞。" },
  { id: 488, part: 5, difficulty: 4, question: "The firm _____ a binding offer for the acquisition of the target company.", options: ["submitted", "made", "presented", "delivered"], answer: 0, explanation: "「submit a binding offer（拘束力のある提案を提出する）」= M&Aプロセスでの正式なオファー提出。" },
  { id: 489, part: 5, difficulty: 4, question: "The board's decision to _____ the dividend was met with disappointment by investors.", options: ["suspend", "cancel", "halt", "freeze"], answer: 0, explanation: "「suspend the dividend（配当を停止する）」= 一時的な配当の中止を示す。cancelは恒久的な廃止。" },
  { id: 490, part: 5, difficulty: 4, question: "The company's _____ improved markedly following the successful debt refinancing.", options: ["creditworthiness", "credit rating", "financial health", "liquidity"], answer: 0, explanation: "「creditworthiness（信用力）」= 資金を借り入れる能力への信頼度を示す総合的な評価。" },
  { id: 491, part: 5, difficulty: 4, question: "The management team has _____ a turnaround plan to restore profitability within 18 months.", options: ["unveiled", "announced", "released", "presented"], answer: 0, explanation: "「unveil a plan（計画を発表する）」= 初めて計画を公表するときに使う動詞。" },
  { id: 492, part: 5, difficulty: 4, question: "The company was _____ for violating environmental regulations and fined ¥50 million.", options: ["penalized", "fined", "charged", "prosecuted"], answer: 0, explanation: "「penalized（罰せられた）」= 制裁・罰則を受けた状態を示す動詞。" },
  { id: 493, part: 5, difficulty: 4, question: "The new CEO is expected to _____ the company's strategic direction.", options: ["reshape", "change", "alter", "transform"], answer: 0, explanation: "「reshape the direction（方向性を再形成する）」= 大きな変革をもたらす動詞。" },
  { id: 494, part: 5, difficulty: 4, question: "The transaction is _____ to close in the second half of next year.", options: ["expected", "anticipated", "projected", "scheduled"], answer: 0, explanation: "「expected to close（成約する見込み）」はM&Aの取引完了予定を示す表現。" },
  { id: 495, part: 5, difficulty: 4, question: "The company is _____ the feasibility of entering the Southeast Asian market.", options: ["assessing", "evaluating", "studying", "examining"], answer: 0, explanation: "「assess feasibility（実現可能性を評価する）」はTOEIC頻出コロケーション。" },
  { id: 496, part: 5, difficulty: 4, question: "The firm has retained a financial advisor to _____ a sale of its non-core assets.", options: ["facilitate", "assist with", "support", "help with"], answer: 0, explanation: "「facilitate a sale（売却を促進する）」= アドバイザーが取引をスムーズに進める動詞。" },
  { id: 497, part: 5, difficulty: 4, question: "The company's _____ expenses fell by 12% year-on-year, reflecting efficiency improvements.", options: ["operating", "operational", "overhead", "administrative"], answer: 0, explanation: "「operating expenses（営業費用）」= 事業運営に直接かかるコスト。財務諸表の必須語彙。" },
  { id: 498, part: 5, difficulty: 4, question: "The _____ team is responsible for maintaining relationships with institutional investors.", options: ["investor relations", "public relations", "communications", "corporate"], answer: 0, explanation: "「investor relations（IR）」= 機関投資家との関係管理を担当する部門・機能。" },
  { id: 499, part: 5, difficulty: 4, question: "The spin-off will allow the parent company to _____ on its core technology business.", options: ["focus", "concentrate", "center", "emphasize"], answer: 0, explanation: "「focus on its core business（コアビジネスに集中する）」はTOEIC超頻出表現。" },
  { id: 500, part: 5, difficulty: 4, question: "The hostile takeover attempt was _____ when the target company found a white knight.", options: ["thwarted", "defeated", "stopped", "prevented"], answer: 0, explanation: "「thwart（阻止する）」= 計画や試みを妨げること。M&A防衛戦術文脈の重要語彙。" },
  { id: 501, part: 5, difficulty: 4, question: "The new compliance framework _____ the processes for reporting potential conflicts of interest.", options: ["streamlines", "simplifies", "clarifies", "outlines"], answer: 0, explanation: "「streamline（効率化する）」= プロセスを単純化・効率化する動詞。" },
  { id: 502, part: 5, difficulty: 4, question: "The company's earnings per share _____ analyst consensus estimates by 15%.", options: ["beat", "exceeded", "surpassed", "outpaced"], answer: 0, explanation: "「beat estimates（予想を上回る）」= 業績が市場コンセンサス予想を超えること。" },
  { id: 503, part: 5, difficulty: 4, question: "The acquisition premium of 30% _____ the target company's strong growth prospects.", options: ["reflected", "showed", "indicated", "justified"], answer: 0, explanation: "「reflect（反映する）」= プレミアムが対象会社の将来性を織り込んでいることを示す。" },
  { id: 504, part: 5, difficulty: 4, question: "The company's shares were _____ from major indices due to the delisting.", options: ["removed", "excluded", "dropped", "taken out"], answer: 0, explanation: "「removed from indices（インデックスから除外された）」= 上場廃止に伴う指数除外。" },
  { id: 505, part: 5, difficulty: 4, question: "The _____ interest rate environment has made borrowing more expensive for all companies.", options: ["rising", "increasing", "higher", "elevated"], answer: 3, explanation: "「elevated interest rate environment（高金利環境）」= 金利が通常より高い状態が続いている状況。" },
  { id: 506, part: 5, difficulty: 4, question: "The company _____ a strategic partnership to strengthen its distribution network in Asia.", options: ["forged", "formed", "established", "built"], answer: 0, explanation: "「forge a partnership（パートナーシップを結ぶ）」= 努力を伴って関係を構築するニュアンス。" },
  { id: 507, part: 5, difficulty: 4, question: "The company's _____ growth rate of 20% is expected to attract significant investor interest.", options: ["projected", "estimated", "forecast", "anticipated"], answer: 0, explanation: "「projected growth rate（予測成長率）」= 経営陣または分析会社が予想する成長率。" },
  { id: 508, part: 5, difficulty: 4, question: "The board _____ that all directors must hold a minimum stake in the company.", options: ["resolved", "decided", "voted", "agreed"], answer: 0, explanation: "「resolve（決議する）」= 取締役会が正式な決議を行う動詞。" },
  { id: 509, part: 5, difficulty: 4, question: "The _____ value of the company has grown substantially since the IPO.", options: ["intrinsic", "enterprise", "market", "book"], answer: 2, explanation: "「market value（時価総額）」= 株式市場で評価される企業の総価値。" },
  { id: 510, part: 5, difficulty: 4, question: "The company is considering _____ its treasury shares to reduce dilution.", options: ["canceling", "retiring", "buying back", "redeeming"], answer: 1, explanation: "「retire treasury shares（自己株式を消却する）」= 自己株式を正式に消滅させる財務処理。" },
  { id: 511, part: 5, difficulty: 4, question: "The CEO _____ the company's long-term vision at the annual investor day event.", options: ["outlined", "presented", "described", "articulated"], answer: 3, explanation: "「articulate a vision（ビジョンを明確に語る）」はCEOの戦略発表に使う上位語。" },
  { id: 512, part: 5, difficulty: 4, question: "The firm has been _____ by regulators for its aggressive accounting practices.", options: ["scrutinized", "investigated", "examined", "probed"], answer: 0, explanation: "「scrutinize（精査する）」= 規制当局が詳細に調査すること。" },
  { id: 513, part: 5, difficulty: 4, question: "The company _____ all outstanding convertible bonds ahead of the acquisition.", options: ["redeemed", "paid off", "settled", "cleared"], answer: 0, explanation: "「redeem convertible bonds（転換社債を償還する）」= 期日前に債券を買い戻す財務処理。" },
  { id: 514, part: 5, difficulty: 4, question: "The _____ of the new facility is expected to be completed by the third quarter.", options: ["commissioning", "opening", "launch", "completion"], answer: 0, explanation: "「commissioning（試運転・完工）」= 新工場・設備が稼働可能な状態になること。" },
  { id: 515, part: 5, difficulty: 4, question: "The management _____ for additional funding to accelerate the expansion plan.", options: ["applied", "sought", "requested", "asked"], answer: 1, explanation: "「seek funding（資金調達を求める）」= 資金獲得のために積極的に働きかける動詞。" },
  { id: 516, part: 5, difficulty: 4, question: "The _____ of the acquisition to the company's earnings will be accretive from year one.", options: ["contribution", "impact", "effect", "addition"], answer: 0, explanation: "「contribution to earnings（収益への貢献）」= 買収が収益を増加させることを示す。" },
  { id: 517, part: 5, difficulty: 4, question: "The company issued new shares to _____ its balance sheet ahead of the expansion.", options: ["strengthen", "bolster", "improve", "enhance"], answer: 1, explanation: "「bolster the balance sheet（貸借対照表を強化する）」= 財務基盤を補強する。" },
  { id: 518, part: 5, difficulty: 4, question: "The joint venture is _____ on securing a 10-year supply agreement.", options: ["contingent", "dependent", "conditional", "subject"], answer: 0, explanation: "「contingent on（〜を条件とする）」はM&A・契約文脈で最も使われる形容詞。" },
  { id: 519, part: 5, difficulty: 4, question: "The board _____ that the company's fundamentals remain strong despite market volatility.", options: ["reaffirmed", "confirmed", "emphasized", "stated"], answer: 0, explanation: "「reaffirm（再確認する）」= 一度確認した事実を改めて強調する動詞。" },
  { id: 520, part: 5, difficulty: 4, question: "The company is _____ to become the first in its industry to achieve net-zero emissions.", options: ["on track", "poised", "expected", "set"], answer: 1, explanation: "「poised to（〜する体制が整っている）」= 一歩手前まで準備が整っているニュアンス。" },
  { id: 521, part: 5, difficulty: 4, question: "The CEO _____ the decision to enter the partnership, citing strategic alignment.", options: ["justified", "defended", "explained", "rationalized"], answer: 0, explanation: "「justify a decision（決断を正当化する）」= 根拠を示して判断の妥当性を説明する。" },
  { id: 522, part: 5, difficulty: 4, question: "The firm has entered into _____ negotiations with three potential acquirers.", options: ["exclusive", "bilateral", "final", "binding"], answer: 0, explanation: "「exclusive negotiations（独占交渉）」= 他の潜在的な買い手を排除した二者間交渉。" },
  { id: 523, part: 5, difficulty: 4, question: "The company _____ a revolving credit facility of ¥50 billion to fund working capital.", options: ["arranged", "secured", "set up", "established"], answer: 1, explanation: "「secure a credit facility（クレジットファシリティを確保する）」= 資金調達ラインを確保する動詞。" },
  { id: 524, part: 5, difficulty: 4, question: "The _____ of the chairman at the AGM was unexpected and raised concerns among investors.", options: ["resignation", "departure", "exit", "withdrawal"], answer: 0, explanation: "「resignation（辞任）」= 役員が自発的に職を辞すること。突然のresignationはコーポレートガバナンス上の重要事項。" },
  { id: 525, part: 5, difficulty: 4, question: "The company has _____ a pioneering position in the use of AI in supply chain management.", options: ["carved out", "established", "built", "developed"], answer: 0, explanation: "「carve out a position（独自のポジションを切り開く）」= 競争の中で差別化した地位を確立する。" },

  // ══ Part 5 Level 5 (IDs 526-625) ══
  { id: 526, part: 5, difficulty: 5, question: "The indemnification clause _____ the acquirer from any pre-closing liabilities of the target.", options: ["insulates", "protects", "shields", "indemnifies"], answer: 3, explanation: "「indemnify（免責する）」= 損害が生じた場合に補償することを法的に約束する動詞。" },
  { id: 527, part: 5, difficulty: 5, question: "The _____ of the earn-out provision is contingent on the target meeting specific EBITDA milestones.", options: ["payout", "payment", "settlement", "disbursement"], answer: 0, explanation: "「payout（支払い）」= アーンアウト条項に基づく条件付き支払いを指す。" },
  { id: 528, part: 5, difficulty: 5, question: "The regulatory authority issued a _____ requiring the company to cease the anticompetitive practices.", options: ["cease-and-desist order", "injunction", "directive", "mandate"], answer: 0, explanation: "「cease-and-desist order（中止命令）」= 特定の行為の即時停止を命じる法的命令。" },
  { id: 529, part: 5, difficulty: 5, question: "The transaction was _____ following the discovery of material misrepresentations during due diligence.", options: ["rescinded", "cancelled", "voided", "terminated"], answer: 0, explanation: "「rescind（取り消す）」= 重大な不実表示を理由に契約を遡及的に無効にする法的行為。" },
  { id: 530, part: 5, difficulty: 5, question: "The _____ of the arbitration award was challenged in the high court by the losing party.", options: ["enforcement", "execution", "implementation", "application"], answer: 0, explanation: "「enforcement of an arbitration award（仲裁判断の執行）」= 仲裁で確定した権利を強制的に実現すること。" },
  { id: 531, part: 5, difficulty: 5, question: "The company _____ a material adverse change clause to exit the merger agreement.", options: ["invoked", "cited", "used", "relied on"], answer: 0, explanation: "「invoke a clause（条項を援用する）」= 契約上の権利を正式に行使すること。" },
  { id: 532, part: 5, difficulty: 5, question: "The share repurchase program was _____ to signal management's confidence in the company's valuation.", options: ["designed", "intended", "structured", "conceived"], answer: 3, explanation: "「conceived to（〜するために構想された）」= 特定の目的のために設計・意図された動詞。" },
  { id: 533, part: 5, difficulty: 5, question: "The audit committee found that the CFO had _____ material facts in the annual disclosures.", options: ["omitted", "concealed", "withheld", "suppressed"], answer: 0, explanation: "「omit material facts（重要事実を省略する）」= 証券規制上問題となる不作為による虚偽記載。" },
  { id: 534, part: 5, difficulty: 5, question: "The new governance framework _____ roles and responsibilities across all board committees.", options: ["delineates", "defines", "clarifies", "specifies"], answer: 0, explanation: "「delineate（明確に区画する）」= 役割・責任の境界を明確に示すフォーマルな動詞。" },
  { id: 535, part: 5, difficulty: 5, question: "The company's auditor issued a qualified opinion, _____ concerns about the going concern assumption.", options: ["citing", "noting", "raising", "highlighting"], answer: 0, explanation: "「cite concerns（懸念を挙げる）」= 監査意見で特定の問題点を根拠として提示する。" },
  { id: 536, part: 5, difficulty: 5, question: "The _____ disclosure requirements compel listed companies to publish insider trading policies.", options: ["mandatory", "obligatory", "compulsory", "required"], answer: 0, explanation: "「mandatory disclosure（強制開示）」= 法律・規則で義務づけられた情報開示。mandatoryは法的文脈の最上位語。" },
  { id: 537, part: 5, difficulty: 5, question: "The acquisition structure included a _____ provision allowing the seller to recover losses if certain warranties proved false.", options: ["clawback", "indemnity", "escrow", "holdback"], answer: 2, explanation: "「escrow provision（エスクロー条項）」= 一部の対価を第三者が保持し、一定条件充足後に引き渡す仕組み。" },
  { id: 538, part: 5, difficulty: 5, question: "The board _____ a poison pill defense mechanism to deter hostile takeover attempts.", options: ["adopted", "instituted", "implemented", "enacted"], answer: 0, explanation: "「adopt a poison pill（ポイズンピルを採用する）」= 敵対的買収防衛策として知られるM&A用語。" },
  { id: 539, part: 5, difficulty: 5, question: "The acquisition _____ the company's EBITDA by approximately ¥3 billion on an annualized basis.", options: ["enhanced", "boosted", "augmented", "accretive to"], answer: 2, explanation: "「augment EBITDA（EBITDAを増加させる）」= 財務指標を増強するフォーマルな動詞。" },
  { id: 540, part: 5, difficulty: 5, question: "The settlement agreement contains a _____ clause preventing either party from commenting publicly.", options: ["non-disparagement", "non-disclosure", "gag", "confidentiality"], answer: 0, explanation: "「non-disparagement clause（誹謗中傷禁止条項）」= 相手方を悪く言うことを禁じる契約条項。" },
  { id: 541, part: 5, difficulty: 5, question: "The underwriters exercised the _____ option to purchase additional shares, reflecting strong investor demand.", options: ["greenshoe", "overallotment", "supplemental", "additional"], answer: 0, explanation: "「greenshoe option（グリーンシューオプション）」= IPO時に引受業者が追加株式を購入できる権利。" },
  { id: 542, part: 5, difficulty: 5, question: "The acquisition premium was _____ by the potential synergies identified during due diligence.", options: ["justified", "supported", "backed", "warranted"], answer: 3, explanation: "「warranted（正当化される）」= 十分な根拠によって正当性が認められること。" },
  { id: 543, part: 5, difficulty: 5, question: "The company is _____ to a comprehensive system of internal controls over financial reporting.", options: ["subject", "bound", "committed", "obligated"], answer: 0, explanation: "「subject to（〜の対象となる）」= 規制・要件の適用を受けることを示す。" },
  { id: 544, part: 5, difficulty: 5, question: "The whistleblower alleged that senior management had _____ the company's revenue figures.", options: ["inflated", "overstated", "manipulated", "falsified"], answer: 0, explanation: "「inflate revenue（収益を水増しする）」= 実際より高く見せかける会計不正を示す。" },
  { id: 545, part: 5, difficulty: 5, question: "The demerger will allow the two resulting entities to _____ their respective capital structures independently.", options: ["optimize", "manage", "structure", "tailor"], answer: 0, explanation: "「optimize capital structure（資本構成を最適化する）」= 各社が独立して財務戦略を最適化できること。" },
  { id: 546, part: 5, difficulty: 5, question: "The _____ of the preliminary injunction prevented the company from proceeding with the asset sale.", options: ["granting", "issuance", "imposition", "application"], answer: 0, explanation: "「granting of an injunction（仮差し止め命令の付与）」= 裁判所が仮処分命令を認めること。" },
  { id: 547, part: 5, difficulty: 5, question: "The management _____ that the divestiture of the consumer division would unlock significant shareholder value.", options: ["contended", "argued", "maintained", "asserted"], answer: 3, explanation: "「assert（主張する）」= 確信を持って強く主張する動詞。フォーマルな文書・声明で使われる。" },
  { id: 548, part: 5, difficulty: 5, question: "The company's _____ governance practices were criticized in a proxy advisory report.", options: ["corporate", "board", "executive", "management"], answer: 0, explanation: "「corporate governance（コーポレートガバナンス）」= 企業統治の仕組み全体を指す必須語彙。" },
  { id: 549, part: 5, difficulty: 5, question: "The leveraged buyout was financed primarily through _____ debt.", options: ["mezzanine", "subordinated", "senior", "hybrid"], answer: 2, explanation: "「senior debt（シニアローン）」= 返済優先順位が最も高い担保付き融資。LBO文脈の必須用語。" },
  { id: 550, part: 5, difficulty: 5, question: "The court ruled that the non-compete clause was _____ broad to be enforceable.", options: ["unduly", "overly", "excessively", "unreasonably"], answer: 0, explanation: "「unduly broad（不当に広い）」= 法的文書で非競争条項の有効性を議論する慣用表現。" },
  { id: 551, part: 5, difficulty: 5, question: "The _____ of the definitive agreement marked the beginning of the statutory merger process.", options: ["execution", "signing", "finalization", "completion"], answer: 0, explanation: "「execution of the definitive agreement（最終合意書の締結）」= 法的拘束力が生じる時点。" },
  { id: 552, part: 5, difficulty: 5, question: "The acquisition was structured as a _____ merger to avoid the target company's change-of-control provisions.", options: ["reverse triangular", "forward triangular", "statutory", "short-form"], answer: 0, explanation: "「reverse triangular merger（逆三角合併）」= チェンジオブコントロール条項を回避するM&A手法。" },
  { id: 553, part: 5, difficulty: 5, question: "The filing _____ that the company's largest shareholder had increased its stake to 15%.", options: ["disclosed", "revealed", "stated", "indicated"], answer: 0, explanation: "「disclose（開示する）」= 証券規制上の義務として情報を公開する動詞。" },
  { id: 554, part: 5, difficulty: 5, question: "The _____ of the new shares will increase the total outstanding count to 200 million.", options: ["issuance", "issue", "release", "creation"], answer: 0, explanation: "「issuance of new shares（新株の発行）」は「issuance」が最もフォーマルな名詞形。" },
  { id: 555, part: 5, difficulty: 5, question: "The board _____ a fairness opinion from an independent investment bank before approving the transaction.", options: ["obtained", "commissioned", "solicited", "requested"], answer: 2, explanation: "「solicit a fairness opinion（フェアネスオピニオンを依頼する）」= M&Aにおける取締役会の義務。" },
  { id: 556, part: 5, difficulty: 5, question: "The company's _____ strategy involves repurchasing shares when the stock trades below intrinsic value.", options: ["capital allocation", "buyback", "shareholder return", "treasury"], answer: 0, explanation: "「capital allocation strategy（資本配分戦略）」= 資本を最も効率的に使う方法を決める戦略。" },
  { id: 557, part: 5, difficulty: 5, question: "The carve-out was designed to _____ the value of the subsidiary that had been obscured within the conglomerate.", options: ["unlock", "release", "realize", "extract"], answer: 0, explanation: "「unlock value（価値を解放する）」= 隠れた価値を顕在化させるM&A文脈の重要表現。" },
  { id: 558, part: 5, difficulty: 5, question: "The covenants in the loan agreement _____ the borrower from making further acquisitions without lender consent.", options: ["restrict", "prohibit", "prevent", "bar"], answer: 0, explanation: "「restrict（制限する）」= ローン契約の誓約条項が特定行為を制限すること。" },
  { id: 559, part: 5, difficulty: 5, question: "The board approved the distribution of _____ dividends to return excess capital to shareholders.", options: ["special", "extraordinary", "one-time", "supplemental"], answer: 0, explanation: "「special dividend（特別配当）」= 通常の配当とは別に支払われる臨時配当。" },
  { id: 560, part: 5, difficulty: 5, question: "The proxy contest _____ when the activist investor nominated four directors to the board.", options: ["escalated", "intensified", "began", "arose"], answer: 0, explanation: "「escalate（激化する）」= 状況がより深刻・激しくなること。委任状争奪戦の文脈で使う。" },
  { id: 561, part: 5, difficulty: 5, question: "The _____ of the company's preferred shares converts automatically upon an IPO.", options: ["conversion", "exchange", "transformation", "shift"], answer: 0, explanation: "「conversion of preferred shares（優先株式の転換）」= 優先株式が普通株式に自動転換される仕組み。" },
  { id: 562, part: 5, difficulty: 5, question: "The company _____ an impairment charge of ¥5 billion related to goodwill from the prior acquisition.", options: ["recorded", "recognized", "booked", "charged"], answer: 1, explanation: "「recognize an impairment charge（減損損失を認識する）」= 会計上の用語。recognizeが最も正確な動詞。" },
  { id: 563, part: 5, difficulty: 5, question: "The _____ covenant requires the company to maintain a minimum interest coverage ratio.", options: ["financial", "maintenance", "affirmative", "incurrence"], answer: 1, explanation: "「maintenance covenant（メンテナンス・コベナンツ）」= 定期的に財務指標の維持を求める誓約条項。" },
  { id: 564, part: 5, difficulty: 5, question: "The company has been _____ to take the underperforming unit private in a management buyout.", options: ["reported", "said", "rumored", "alleged"], answer: 2, explanation: "「rumored to（〜すると噂されている）」= 確認されていない情報として報じられている状態。" },
  { id: 565, part: 5, difficulty: 5, question: "The registration statement was _____ with the securities regulator to initiate the IPO process.", options: ["filed", "submitted", "lodged", "deposited"], answer: 0, explanation: "「file a registration statement（登録届出書を提出する）」= IPO開始の法的手続き。" },
  { id: 566, part: 5, difficulty: 5, question: "The _____ of the transaction is subject to the receipt of necessary governmental approvals.", options: ["closing", "completion", "finalization", "consummation"], answer: 3, explanation: "「consummation（最終完了）」= 取引が法的・実質的に完了した状態を示す最もフォーマルな語。" },
  { id: 567, part: 5, difficulty: 5, question: "The proxy statement _____ all material related-party transactions during the preceding fiscal year.", options: ["discloses", "reveals", "reports", "lists"], answer: 0, explanation: "「disclose related-party transactions（関連当事者取引を開示する）」= 証券規制上の開示義務。" },
  { id: 568, part: 5, difficulty: 5, question: "The management _____ the minority shareholders with a buyout offer at a substantial premium.", options: ["approached", "presented", "offered", "tendered to"], answer: 0, explanation: "「approach minority shareholders（少数株主にアプローチする）」= 非公式な接触から開始するM&Aの初期プロセス。" },
  { id: 569, part: 5, difficulty: 5, question: "The _____ of the merger agreement was successfully challenged by a competing bidder.", options: ["exclusivity", "lock-up", "termination fee", "break-up fee"], answer: 3, explanation: "「break-up fee（ブレークアップフィー）」= 他の買い手が入ってきた場合に支払われる違約金。" },
  { id: 570, part: 5, difficulty: 5, question: "The transaction structure was _____ to achieve the most favorable tax treatment for the acquirer.", options: ["optimized", "structured", "designed", "tailored"], answer: 0, explanation: "「optimize the transaction structure（スキームを最適化する）」= 税務・財務上の最善の結果を目指す。" },
  { id: 571, part: 5, difficulty: 5, question: "The _____ of the litigation risk remains a key concern for potential investors.", options: ["materiality", "magnitude", "extent", "scale"], answer: 0, explanation: "「materiality of litigation risk（訴訟リスクの重要性）」= 会計・証券開示上の重要性概念。" },
  { id: 572, part: 5, difficulty: 5, question: "The firm's investment committee _____ on the proposed private equity investment after a rigorous review.", options: ["deliberated", "voted", "decided", "ruled"], answer: 0, explanation: "「deliberate on（〜について熟考する）」= 委員会が慎重に議論・審議する動詞。" },
  { id: 573, part: 5, difficulty: 5, question: "The _____ of the company's pension obligations necessitated a significant contribution to the pension fund.", options: ["underfunding", "shortfall", "deficit", "gap"], answer: 0, explanation: "「underfunding（積立不足）」= 年金基金の積立額が債務に対して不足している状態。" },
  { id: 574, part: 5, difficulty: 5, question: "The board _____ the hostile takeover bid, citing the inadequacy of the offer price.", options: ["rejected", "rebuffed", "dismissed", "spurned"], answer: 1, explanation: "「rebuff（きっぱりと拒否する）」= 相手の提案を断固として退けるニュアンスの動詞。" },
  { id: 575, part: 5, difficulty: 5, question: "The _____ of the derivative suit was contingent on demonstrating that the directors had breached their fiduciary duties.", options: ["success", "viability", "merit", "outcome"], answer: 2, explanation: "「merit of a derivative suit（株主代表訴訟の当否）」= 訴訟の正当性・妥当性を示す法律用語。" },
  { id: 576, part: 5, difficulty: 5, question: "The acquisition agreement contained a _____ provision allowing the target to solicit competing bids for 45 days.", options: ["go-shop", "market check", "fiduciary out", "no-shop"], answer: 0, explanation: "「go-shop provision（ゴーショップ条項）」= 合意後も一定期間他の入札者を探せる条項。" },
  { id: 577, part: 5, difficulty: 5, question: "The _____ structure of the deal involved contingent payments tied to post-closing performance.", options: ["earn-out", "milestone", "contingent value", "deferred payment"], answer: 0, explanation: "「earn-out structure（アーンアウト構造）」= 将来業績に連動した追加対価の支払い仕組み。" },
  { id: 578, part: 5, difficulty: 5, question: "The company _____ its shares at a price that was considered accretive to existing shareholders.", options: ["repurchased", "bought back", "reacquired", "retired"], answer: 0, explanation: "「repurchase shares（自己株式を買い戻す）」は「share repurchase program」として定着した表現。" },
  { id: 579, part: 5, difficulty: 5, question: "The _____ of the acquisition price was based on a multiple of the target's trailing twelve-month EBITDA.", options: ["determination", "calculation", "derivation", "valuation"], answer: 3, explanation: "「valuation（バリュエーション）」= EBITDAマルチプルによる企業価値評価。" },
  { id: 580, part: 5, difficulty: 5, question: "The board concluded that the unsolicited bid _____ the true intrinsic value of the company.", options: ["undervalued", "underestimated", "failed to reflect", "discounted"], answer: 0, explanation: "「undervalue（過小評価する）」= 実際の価値より低く見積もること。" },
  { id: 581, part: 5, difficulty: 5, question: "The _____ provisions of the shareholders' agreement prevent any party from transferring shares without prior consent.", options: ["lock-up", "transfer restriction", "anti-dilution", "tag-along"], answer: 1, explanation: "「transfer restriction provisions（譲渡制限条項）」= 株主間協定で定められる株式譲渡の制限。" },
  { id: 582, part: 5, difficulty: 5, question: "The company _____ its earnings guidance following weaker-than-expected results in the third quarter.", options: ["lowered", "revised downward", "cut", "downgraded"], answer: 1, explanation: "「revised downward（下方修正した）」= 業績予想の下方修正を示す最もフォーマルな表現。" },
  { id: 583, part: 5, difficulty: 5, question: "The _____ period following the IPO restricts existing shareholders from selling their shares for 180 days.", options: ["lock-up", "hold", "blackout", "quiet"], answer: 0, explanation: "「lock-up period（ロックアップ期間）」= IPO後に既存株主が株式を売却できない期間。" },
  { id: 584, part: 5, difficulty: 5, question: "The restructuring plan was designed to _____ the company's cost base by approximately 20%.", options: ["rationalize", "reduce", "streamline", "optimize"], answer: 0, explanation: "「rationalize the cost base（コスト構造を合理化する）」= 不必要なコストを排除して効率化すること。" },
  { id: 585, part: 5, difficulty: 5, question: "The hedge fund _____ the company's management to provide better disclosure of its real estate holdings.", options: ["pressured", "urged", "lobbied", "pushed"], answer: 0, explanation: "「pressure management（経営陣に圧力をかける）」= アクティビスト投資家が変革を求める動詞。" },
  { id: 586, part: 5, difficulty: 5, question: "The company's _____ ratio declined to 1.2x following the leveraged buyout, raising liquidity concerns.", options: ["interest coverage", "debt-to-equity", "current", "quick"], answer: 0, explanation: "「interest coverage ratio（インタレストカバレッジレシオ）」= EBITを利息費用で割った財務健全性指標。" },
  { id: 587, part: 5, difficulty: 5, question: "The independent directors _____ a special committee to evaluate the going-private transaction.", options: ["established", "formed", "constituted", "convened"], answer: 2, explanation: "「constitute a special committee（特別委員会を組織する）」= 利益相反取引を評価するための独立委員会設置。" },
  { id: 588, part: 5, difficulty: 5, question: "The _____ of the reverse merger allowed the private company to access public markets without a traditional IPO.", options: ["mechanics", "structure", "rationale", "benefit"], answer: 2, explanation: "「rationale（根拠・理由）」= 逆さ合併を選択した理由・論拠を示す。" },
  { id: 589, part: 5, difficulty: 5, question: "The company _____ a secondary offering to allow early-stage investors to liquidate their positions.", options: ["completed", "conducted", "executed", "priced"], answer: 3, explanation: "「price a secondary offering（セカンダリーオファリングを価格決定する）」= 株式の公募増資の価格決定を行うIPO・株式市場用語。" },
  { id: 590, part: 5, difficulty: 5, question: "The activist investor _____ a public letter to the board calling for the separation of the CEO and chairman roles.", options: ["published", "released", "sent", "issued"], answer: 3, explanation: "「issue a public letter（公開書簡を出す）」= アクティビスト投資家が経営陣に圧力をかける手段。" },
  { id: 591, part: 5, difficulty: 5, question: "The fairness opinion _____ that the consideration to be received by shareholders was fair from a financial point of view.", options: ["concluded", "stated", "found", "determined"], answer: 0, explanation: "「conclude（結論づける）」= フェアネスオピニオンにおける最終的な判断を示す動詞。" },
  { id: 592, part: 5, difficulty: 5, question: "The _____ between the two companies will allow them to develop and market the new technology jointly.", options: ["alliance", "partnership", "collaboration", "consortium"], answer: 3, explanation: "「consortium（コンソーシアム）」= 特定プロジェクトのために複数企業が組成する共同事業体。" },
  { id: 593, part: 5, difficulty: 5, question: "The company _____ a dividend reinvestment plan to encourage long-term share ownership.", options: ["instituted", "established", "implemented", "introduced"], answer: 0, explanation: "「institute a plan（制度を設ける）」= 正式な制度・プログラムを設立する動詞。" },
  { id: 594, part: 5, difficulty: 5, question: "The _____ of the acquisition was subsequently reviewed by the antitrust authority.", options: ["rationale", "terms", "structure", "legality"], answer: 3, explanation: "「legality（合法性）」= 独占禁止法上の観点から買収の法的適合性を審査すること。" },
  { id: 595, part: 5, difficulty: 5, question: "The company _____ its buyback program, repurchasing ¥20 billion of shares over the past fiscal year.", options: ["executed", "completed", "conducted", "implemented"], answer: 0, explanation: "「execute a buyback program（自社株買いプログラムを実行する）」= 計画通りに実施したことを示す動詞。" },
  { id: 596, part: 5, difficulty: 5, question: "The _____ between the projected and actual EBITDA triggered a partial clawback of the earn-out payment.", options: ["shortfall", "gap", "discrepancy", "variance"], answer: 3, explanation: "「variance（差異・乖離）」= 予測値と実績値の差を示す財務・会計用語。" },
  { id: 597, part: 5, difficulty: 5, question: "The board _____ its fiduciary duties by seeking a fairness opinion before approving the related-party transaction.", options: ["discharged", "fulfilled", "met", "satisfied"], answer: 0, explanation: "「discharge fiduciary duties（受託者責任を果たす）」= 取締役がその義務を正式に遂行すること。" },
  { id: 598, part: 5, difficulty: 5, question: "The company's _____ position improved as a result of the successful bond refinancing at a lower coupon rate.", options: ["debt service", "liquidity", "solvency", "leverage"], answer: 1, explanation: "「liquidity position（流動性ポジション）」= 短期的な現金繰りの状況。改善された文脈に合う。" },
  { id: 599, part: 5, difficulty: 5, question: "The _____ arrangement allows the venture to distribute profits to partners based on their capital contributions.", options: ["waterfall", "distribution", "allocation", "split"], answer: 0, explanation: "「waterfall arrangement（ウォーターフォール配分）」= キャッシュフローを優先順位に従って分配する仕組み。" },
  { id: 600, part: 5, difficulty: 5, question: "The acquisition was structured as a _____ purchase to allow the buyer to step up the tax basis of the acquired assets.", options: ["338(h)(10)", "asset", "stock", "merger"], answer: 1, explanation: "「asset purchase（資産取得）」= 対象会社の資産を直接取得することで税務上の基礎価額を引き上げられる取得方式。" },
  { id: 601, part: 5, difficulty: 5, question: "The board _____ its obligation to act in the best interests of shareholders by approving the higher bid.", options: ["fulfilled", "met", "discharged", "satisfied"], answer: 2, explanation: "「discharge an obligation（義務を果たす）」= 法的・倫理的義務を正式に遂行すること。" },
  { id: 602, part: 5, difficulty: 5, question: "The _____ of the working capital adjustment mechanism ensures that the purchase price reflects the company's financial state at closing.", options: ["purpose", "function", "rationale", "objective"], answer: 2, explanation: "「rationale（趣旨・論拠）」= メカニズムの設計理由や目的を示すフォーマルな語。" },
  { id: 603, part: 5, difficulty: 5, question: "The company's revenue _____ from a single customer exceeds 30%, creating significant concentration risk.", options: ["derived", "generated", "earned", "obtained"], answer: 0, explanation: "「revenue derived from（〜から派生する収益）」= 特定顧客への収益依存度を示す表現。" },
  { id: 604, part: 5, difficulty: 5, question: "The _____ of the acquisition price to tangible book value exceeded 3x, reflecting significant goodwill.", options: ["premium", "multiple", "ratio", "markup"], answer: 1, explanation: "「multiple to book value（帳簿価額に対するマルチプル）」= 企業価値評価の指標。" },
  { id: 605, part: 5, difficulty: 5, question: "The company _____ a significant portion of its revenue through long-term contracts with blue-chip clients.", options: ["secures", "generates", "derives", "earns"], answer: 2, explanation: "「derive revenue through contracts（契約から収益を得る）」= 収益の源泉を示すフォーマルな表現。" },
  { id: 606, part: 5, difficulty: 5, question: "The _____ of the litigation was settled for an undisclosed sum, avoiding a potentially damaging public trial.", options: ["outcome", "conclusion", "resolution", "settlement"], answer: 3, explanation: "「settlement（和解）」= 裁判に至る前または途中での合意による解決。" },
  { id: 607, part: 5, difficulty: 5, question: "The fund manager _____ the position after the company missed earnings for three consecutive quarters.", options: ["exited", "sold out", "divested", "liquidated"], answer: 3, explanation: "「liquidate a position（ポジションを清算する）」= 保有株式をすべて売却することを示す投資用語。" },
  { id: 608, part: 5, difficulty: 5, question: "The _____ of the convertible note was triggered when the company raised ¥1 billion in a subsequent financing round.", options: ["conversion", "exercise", "redemption", "settlement"], answer: 0, explanation: "「conversion of a convertible note（転換社債の転換）」= 一定条件で社債が株式に転換される。" },
  { id: 609, part: 5, difficulty: 5, question: "The deferred tax _____ was recognized in connection with the accelerated depreciation of newly acquired assets.", options: ["liability", "asset", "obligation", "benefit"], answer: 0, explanation: "「deferred tax liability（繰延税金負債）」= 税務と会計の一時的差異から生じる負債。" },
  { id: 610, part: 5, difficulty: 5, question: "The company _____ the threshold for triggering the rights plan by accumulating a 20% stake in the company.", options: ["crossed", "exceeded", "breached", "surpassed"], answer: 2, explanation: "「breach the threshold（閾値を超える）」= 権利行使の発動条件を超えること。違反のニュアンスを含む。" },
  { id: 611, part: 5, difficulty: 5, question: "The _____ of the restructuring included the elimination of two business units and the sale of three manufacturing plants.", options: ["scope", "extent", "scale", "breadth"], answer: 0, explanation: "「scope of the restructuring（リストラの範囲）」= 再編の対象範囲を示す。" },
  { id: 612, part: 5, difficulty: 5, question: "The company _____ its projections for the year, citing headwinds from foreign exchange fluctuations.", options: ["downgraded", "revised", "cut", "lowered"], answer: 1, explanation: "「revise projections（予測を修正する）」= 業績見通しを改訂する動詞。downgradeは格付けに使う。" },
  { id: 613, part: 5, difficulty: 5, question: "The _____ of the company's workforce by 15% was announced as part of a broader restructuring program.", options: ["reduction", "downsizing", "rationalization", "trimming"], answer: 2, explanation: "「workforce rationalization（人員の合理化）」= 組織効率化のための人員削減を示すフォーマルな表現。" },
  { id: 614, part: 5, difficulty: 5, question: "The board _____ a standstill agreement with the activist investor to pause the proxy contest.", options: ["negotiated", "entered into", "signed", "agreed to"], answer: 1, explanation: "「enter into a standstill agreement（スタンドスティル合意を締結する）」= 敵対的行動を一時停止する合意。" },
  { id: 615, part: 5, difficulty: 5, question: "The prospectus _____ material risk factors including competitive pressures and regulatory uncertainty.", options: ["identifies", "lists", "discloses", "describes"], answer: 2, explanation: "「disclose risk factors（リスク要因を開示する）」= 目論見書の法的開示義務を示す動詞。" },
  { id: 616, part: 5, difficulty: 5, question: "The company's _____ ratio fell below the covenant threshold, triggering a lender review.", options: ["leverage", "interest coverage", "debt service coverage", "current"], answer: 2, explanation: "「debt service coverage ratio（デットサービスカバレッジレシオ）」= 元利金返済能力を示す財務指標。" },
  { id: 617, part: 5, difficulty: 5, question: "The acquisition is _____ accretive to the acquirer's earnings per share in the first full year of operations.", options: ["projected", "expected", "estimated", "anticipated"], answer: 0, explanation: "「projected accretive（のれん増加が見込まれる）」= 買収がEPS増加をもたらすと予測されることを示す。" },
  { id: 618, part: 5, difficulty: 5, question: "The _____ interest of the private equity fund was 20% of the profits above the hurdle rate.", options: ["carried", "promoted", "performance", "incentive"], answer: 0, explanation: "「carried interest（キャリードインタレスト）」= 運用パフォーマンスに応じたPEファンドへの報酬。" },
  { id: 619, part: 5, difficulty: 5, question: "The restructuring advisor was retained to _____ a comprehensive out-of-court debt restructuring.", options: ["facilitate", "manage", "conduct", "oversee"], answer: 0, explanation: "「facilitate a restructuring（リストラを促進する）」= アドバイザーが当事者間の合意形成を支援する動詞。" },
  { id: 620, part: 5, difficulty: 5, question: "The _____ of the spin-off entity was priced at a significant discount to peers to attract investor interest.", options: ["IPO", "listing", "float", "offering"], answer: 2, explanation: "「float（上場・株式公開）」= 企業の株式を初めて市場で売り出すこと。IPOと同義だが動詞としても使う。" },
  { id: 621, part: 5, difficulty: 5, question: "The company's _____ to pursue organic growth over acquisitions was reflected in its modest capital expenditure guidance.", options: ["preference", "commitment", "strategy", "approach"], answer: 0, explanation: "「preference for organic growth（有機的成長への選好）」= 買収よりも自社成長を優先する経営方針。" },
  { id: 622, part: 5, difficulty: 5, question: "The lenders _____ a waiver to allow the company to breach the leverage covenant for two quarters.", options: ["granted", "provided", "gave", "issued"], answer: 0, explanation: "「grant a waiver（免除・猶予を付与する）」= レンダーがコベナンツ違反の一時的な猶予を認めること。" },
  { id: 623, part: 5, difficulty: 5, question: "The board established a _____ committee to oversee the negotiation of the going-private transaction.", options: ["special", "independent", "ad hoc", "standing"], answer: 0, explanation: "「special committee（特別委員会）」= 利益相反取引を監督するために設置される独立委員会。" },
  { id: 624, part: 5, difficulty: 5, question: "The merger agreement included a _____ fee of ¥5 billion payable to the acquirer if the deal was terminated.", options: ["reverse break-up", "termination", "break-up", "exit"], answer: 0, explanation: "「reverse break-up fee（リバースブレークアップフィー）」= 買い手側の事情で取引が破談になった場合に買い手が売り手に支払う違約金。" },
  { id: 625, part: 5, difficulty: 5, question: "The company _____ its liability under the environmental remediation obligation by purchasing pollution insurance.", options: ["capped", "limited", "reduced", "hedged"], answer: 3, explanation: "「hedge a liability（負債リスクをヘッジする）」= 保険購入によってリスクを軽減することを示す。" },

];
